_QF = {"ui": None, "display": None, "mono": None, "picked": False}


def _qt_pick_fonts():
    if _QF["picked"]:
        return
    try:
        fams = {f.lower(): f for f in QFontDatabase.families()}
    except Exception:
        fams = {}

    def first(*names):
        for n in names:
            if n.lower() in fams:
                return fams[n.lower()]
        return None
    ui = first("Segoe UI Variable Text", "Segoe UI", "Inter", "Noto Sans", "Cantarell", "DejaVu Sans", "Arial")
    _QF["ui"] = ui or QApplication.font().family()
    _QF["display"] = first("Segoe UI Variable Display", "Segoe UI Variable Text", "Inter Display", "Segoe UI", "Inter") or _QF["ui"]
    _QF["mono"] = first("Cascadia Mono", "Cascadia Code", "JetBrains Mono", "Consolas", "DejaVu Sans Mono", "Courier New") or "monospace"
    _QF["picked"] = True
    plog("UI", f"fonts: ui={_QF['ui']} display={_QF['display']} mono={_QF['mono']}")


_QF_WEIGHT = {"light": 300, "normal": 400, "medium": 500, "semi": 600, "bold": 700, "heavy": 800}


def QF(kind="ui", size=10, weight="normal"):
    _qt_pick_fonts()
    fam = _QF.get(kind) or _QF["ui"]
    f = QFont(fam)
    f.setPointSizeF(max(6.5, float(size) + float(_STUDIO.get("delta", 0) or 0)))
    if kind == "display" and weight == "normal":
        weight = "semi"
    f.setWeight(QFont.Weight(_QF_WEIGHT.get(weight, 400)))
    if kind == "mono":
        f.setStyleHint(QFont.StyleHint.Monospace)
    f.setHintingPreference(QFont.HintingPreference.PreferVerticalHinting)
    return f


def qc(c, alpha=None):
    col = QColor(_hx(c) if isinstance(c, str) else c)
    if alpha is not None:
        col.setAlphaF(max(0.0, min(1.0, float(alpha))))
    return col


