_EASE = {
    "out": QEasingCurve.Type.OutCubic, "in": QEasingCurve.Type.InCubic, "inout": QEasingCurve.Type.InOutCubic,
    "back": QEasingCurve.Type.OutBack, "linear": QEasingCurve.Type.Linear, "quart": QEasingCurve.Type.OutQuart,
    "expo": QEasingCurve.Type.OutExpo, "sine": QEasingCurve.Type.InOutSine,
}


class _QtMotion:
    LEVELS = {"off": 0, "reduced": 1, "full": 2}

    def __init__(self):
        self.level = 2
        self._tw = {}
        self._val = {}
        self._loops = {}
        self._timer = None
        self._born = time.perf_counter()
        self.frames = 0
        self.fps = 0.0
        self._fps_n = 0
        self._fps_t = time.perf_counter()
        self.worst_ms = 0.0
        self.errors = 0
        self.window = None

    @property
    def on(self):
        return self.level > 0

    @property
    def ambient(self):
        return self.level >= 2

    def set_level(self, level):
        lv = self.LEVELS.get(str(level), 2) if not isinstance(level, int) else max(0, min(2, level))
        self.level = lv
        if lv == 0:
            for key in list(self._tw):
                self.finish(key)
        if lv < 2:
            for key, lp in list(self._loops.items()):
                self._safe(lp["fn"], 0.0)
        self._kick()

    def ms(self, d):
        if self.level == 0:
            return 0
        return int(d * (0.55 if self.level == 1 else 1.0))

    def _safe(self, fn, *a):
        try:
            fn(*a)
            return True
        except RuntimeError:
            return False
        except Exception as _ex:
            self.errors += 1
            _trace(_ex_where(), _ex)
            return False

    def value(self, key, default=0.0):
        return self._val.get(key, default)

    def tween(self, key, dur, fn, b=1.0, a=None, ease="out", done=None, delay=0):
        if threading.current_thread() is not threading.main_thread():
            app = globals().get("main_gui_application")
            if app is not None:
                app.ui(self.tween, key, dur, fn, b, a, ease, done, delay)
            return
        if a is None:
            a = self._val.get(key, 0.0 if b else 1.0)
        self.cancel(key)
        d = self.ms(dur)
        if d <= 0:
            self._val[key] = b
            if self._safe(fn, b) and done is not None:
                self._safe(done)
            return
        an = QVariantAnimation()
        an.setStartValue(float(a))
        an.setEndValue(float(b))
        an.setDuration(int(d))
        curve = QEasingCurve(_EASE.get(ease, ease) if not isinstance(ease, QEasingCurve.Type) else ease)
        if ease == "back":
            curve.setOvershoot(1.35)
        an.setEasingCurve(curve)

        def _step(v, key=key, an=an):
            self._val[key] = float(v)
            if not self._safe(fn, float(v)):
                an.stop()
        an.valueChanged.connect(_step)

        def _fin(key=key, an=an):
            if self._tw.get(key) is an:
                del self._tw[key]
            if done is not None:
                self._safe(done)
        an.finished.connect(_fin)
        self._tw[key] = an
        self._val[key] = float(a)
        if delay > 0 and self.on:
            QTimer.singleShot(int(self.ms(delay)), lambda an=an, key=key: an.start() if self._tw.get(key) is an else None)
        else:
            an.start()

    def color(self, key, dur, setter, to, frm=None, ease="out", done=None, delay=0):
        start = frm or self._val.get(("c", key)) or to
        self._val[("c", key)] = to
        if _hx(start) == _hx(to):
            self._safe(setter, to)
            if done is not None:
                self._safe(done)
            return
        self.tween(key, dur, lambda p, s=start, t=to: setter(mix(s, t, max(0.0, min(1.0, p)))), 1.0, 0.0, ease, done, delay)

    def busy(self, key):
        an = self._tw.get(key)
        return an is not None and an.state() == QAbstractAnimation.State.Running

    def cancel(self, key):
        an = self._tw.pop(key, None)
        if an is not None:
            try:
                an.stop()
            except RuntimeError:
                pass

    def finish(self, key):
        an = self._tw.pop(key, None)
        if an is None:
            return
        try:
            end = an.endValue()
            an.stop()
            an.valueChanged.emit(end)
            an.finished.emit()
        except RuntimeError:
            pass

    def loop(self, key, fn, period_ms, fps=30):
        if key in self._loops:
            self._loops[key]["period"] = period_ms / 1000.0
            return
        self._loops[key] = {"fn": fn, "period": period_ms / 1000.0, "born": time.perf_counter(),
                            "step": 1.0 / max(1, fps), "last": 0.0}
        if not self.ambient:
            self._safe(fn, 0.0)
        self._kick()

    def unloop(self, key, rest=True):
        lp = self._loops.pop(key, None)
        if lp is not None and rest:
            self._safe(lp["fn"], 0.0)

    def looping(self, key):
        return key in self._loops

    def _kick(self):
        if self._timer is None:
            if QApplication.instance() is None:
                return
            self._timer = QTimer()
            self._timer.setTimerType(Qt.TimerType.PreciseTimer)
            self._timer.timeout.connect(self._frame)
        want = bool(self._loops) and self.ambient
        if want and not self._timer.isActive():
            self._timer.start(16)
        elif not want and self._timer.isActive():
            self._timer.stop()

    def _frame(self):
        w = self.window
        if w is not None:
            try:
                if w.isMinimized() or not w.isVisible():
                    return
            except RuntimeError:
                return
        t0 = time.perf_counter()
        for key, lp in list(self._loops.items()):
            if t0 - lp["last"] < lp["step"]:
                continue
            lp["last"] = t0
            ph = ((t0 - lp["born"]) / lp["period"]) % 1.0 if lp["period"] > 0 else 0.0
            if not self._safe(lp["fn"], ph):
                self._loops.pop(key, None)
        el = (time.perf_counter() - t0) * 1000.0
        self.frames += 1
        self._fps_n += 1
        self.worst_ms = max(self.worst_ms, el)
        if t0 - self._fps_t >= 1.0:
            self.fps = self._fps_n / (t0 - self._fps_t)
            self._fps_n = 0
            self._fps_t = t0
        if not self._loops:
            self._kick()

    def stats(self):
        names = {0: "off", 1: "reduced", 2: "full"}
        return f"{names.get(self.level, '?')} tweens={len(self._tw)} loops={len(self._loops)} fps={self.fps:.0f} worst={self.worst_ms:.0f}ms"


MOTION = _QtMotion()


class _QtBridge(QObject):
    wake = pyqtSignal()

    def __init__(self, app):
        super().__init__()
        self.app = app
        self._pending = False
        self.wake.connect(self._run, Qt.ConnectionType.QueuedConnection)

    def poke(self):
        if not self._pending:
            self._pending = True
            try:
                self.wake.emit()
            except RuntimeError:
                self._pending = False

    def _run(self):
        self._pending = False
        try:
            self.app._drain_ui_calls(budget=0.03)
        except Exception as _ex:
            _trace(_ex_where(), _ex)
        q = getattr(self.app, "_ui_q", None)
        if q is not None and not q.empty():
            QTimer.singleShot(4, self.poke)


def _on_main():
    return threading.current_thread() is threading.main_thread()


def qt_call_sync(fn, *a, timeout=900, **k):
    if _on_main() or QApplication.instance() is None:
        return fn(*a, **k)
    app = globals().get("main_gui_application")
    if app is None:
        return fn(*a, **k)
    box = {"v": None, "e": None}
    ev = threading.Event()

    def run():
        try:
            box["v"] = fn(*a, **k)
        except Exception as e:
            box["e"] = e
        finally:
            ev.set()
    app.ui(run)
    ev.wait(timeout)
    if box["e"] is not None:
        raise box["e"]
    return box["v"]


class QtRoot:
    def __init__(self, qapp, win):
        self.qapp = qapp
        self.win = win
        self._timers = {}
        self._seq = 0

    def after(self, ms, fn=None, *a):
        if fn is None:
            return None
        if not _on_main():
            app = globals().get("main_gui_application")
            if app is not None:
                app.ui(self.after, ms, fn, *a)
            return None
        self._seq += 1
        tid = f"after#{self._seq}"
        t = QTimer(self.win)
        t.setSingleShot(True)

        def fire(tid=tid, fn=fn, a=a):
            tm = self._timers.pop(tid, None)
            if tm is not None:
                tm.deleteLater()
            try:
                fn(*a)
            except Exception as e:
                log_crash(f"after callback {getattr(fn, '__name__', '?')}", e)
        t.timeout.connect(fire)
        self._timers[tid] = t
        t.start(max(0, int(ms)))
        return tid

    def after_idle(self, fn, *a):
        return self.after(0, fn, *a)

    def after_cancel(self, tid):
        t = self._timers.pop(tid, None)
        if t is not None:
            try:
                t.stop()
                t.deleteLater()
            except RuntimeError:
                pass

    def pending(self):
        return len(self._timers)

    def title(self, text=None):
        if text is None:
            return self.win.windowTitle()
        self.win.setWindowTitle(str(text))

    def update(self):
        try:
            self.qapp.processEvents()
        except Exception:
            pass

    update_idletasks = update

    def iconify(self):
        self.win.showMinimized()

    def deiconify(self):
        self.win.showNormal()
        self.win.raise_()
        self.win.activateWindow()

    def state(self):
        return "iconic" if self.win.isMinimized() else "normal"

    def winfo_width(self):
        return self.win.width()

    def winfo_height(self):
        return self.win.height()

    def winfo_rootx(self):
        return self.win.geometry().x()

    def winfo_rooty(self):
        return self.win.geometry().y()

    winfo_x = winfo_rootx
    winfo_y = winfo_rooty

    def winfo_screenwidth(self):
        sc = self.win.screen() or QApplication.primaryScreen()
        return sc.availableGeometry().width() if sc else 1920

    def winfo_screenheight(self):
        sc = self.win.screen() or QApplication.primaryScreen()
        return sc.availableGeometry().height() if sc else 1080

    def winfo_viewable(self):
        return self.win.isVisible() and not self.win.isMinimized()

    def clipboard_clear(self):
        QApplication.clipboard().setText("")

    def clipboard_append(self, text):
        cb = QApplication.clipboard()
        cb.setText(cb.text() + str(text))

    def clipboard_set(self, text):
        QApplication.clipboard().setText(str(text))

    def attributes(self, *a):
        if len(a) >= 2 and a[0] == "-alpha":
            self.win.setWindowOpacity(max(0.0, min(1.0, float(a[1]))))
        elif len(a) >= 2 and a[0] == "-topmost":
            self.win.setWindowFlag(Qt.WindowType.WindowStaysOnTopHint, bool(a[1]))
            self.win.show()

    def focus_get(self):
        return QApplication.focusWidget()

    def destroy(self):
        try:
            self.win.close()
        except Exception:
            pass
        self.qapp.quit()

    def mainloop(self):
        return self.qapp.exec()


def _qt_filter(filetypes):
    out = []
    for ft in filetypes or []:
        try:
            name, pat = ft
        except Exception:
            continue
        pats = pat if isinstance(pat, (list, tuple)) else str(pat).split()
        out.append(f"{name} ({' '.join(pats)})")
    out.append("All files (*)")
    return ";;".join(out)


def _dlg_parent():
    app = globals().get("main_gui_application")
    win = getattr(app, "win", None) if app is not None else None
    return win


class _QtMessageBox:
    def _show(self, kind, title, message, buttons):
        def run():
            if QApplication.instance() is None:
                print(f"[{kind}] {title}: {message}")
                return buttons[0][1] if buttons else None
            dlg = ModernDialog(_dlg_parent(), str(title), str(message), kind, buttons)
            return dlg.run()
        try:
            return qt_call_sync(run)
        except Exception as e:
            _trace(_ex_where(), e)
            return None

    def showinfo(self, title="", message="", **kw):
        self._show("info", title, message, [("OK", True, "primary")])

    def showwarning(self, title="", message="", **kw):
        self._show("warn", title, message, [("OK", True, "primary")])

    def showerror(self, title="", message="", **kw):
        self._show("bad", title, message, [("OK", True, "primary")])

    def askyesno(self, title="", message="", **kw):
        return bool(self._show("ask", title, message, [("No", False, "neutral"), ("Yes", True, "primary")]))

    def askokcancel(self, title="", message="", **kw):
        return bool(self._show("ask", title, message, [("Cancel", False, "neutral"), ("OK", True, "primary")]))


class _QtFileDialog:
    def askopenfilename(self, title="Open", filetypes=None, initialdir="", **kw):
        def run():
            fp, _ = QFileDialog.getOpenFileName(_dlg_parent(), str(title), str(initialdir or ""), _qt_filter(filetypes))
            return fp or ""
        return qt_call_sync(run)

    def asksaveasfilename(self, title="Save", defaultextension="", initialfile="", filetypes=None, initialdir="", **kw):
        def run():
            start = os.path.join(str(initialdir or ""), str(initialfile or "")) if (initialdir or initialfile) else ""
            fp, _ = QFileDialog.getSaveFileName(_dlg_parent(), str(title), start, _qt_filter(filetypes))
            if fp and defaultextension and not os.path.splitext(fp)[1]:
                fp += defaultextension
            return fp or ""
        return qt_call_sync(run)

    def askdirectory(self, title="Choose a folder", initialdir="", **kw):
        def run():
            return QFileDialog.getExistingDirectory(_dlg_parent(), str(title), str(initialdir or "")) or ""
        return qt_call_sync(run)


class _QtSimpleDialog:
    def askstring(self, title="", prompt="", show=None, initialvalue=None, parent=None, **kw):
        def run():
            if QApplication.instance() is None:
                return None
            dlg = ModernDialog(_dlg_parent(), str(title), str(prompt), "ask",
                               [("Cancel", None, "neutral"), ("OK", True, "primary")],
                               field=str(initialvalue or ""), secret=bool(show))
            res = dlg.run()
            return dlg.field_value if res else None
        return qt_call_sync(run)

    def askinteger(self, title="", prompt="", initialvalue=None, minvalue=None, maxvalue=None, **kw):
        v = self.askstring(title, prompt, initialvalue=initialvalue)
        if v is None:
            return None
        try:
            n = int(str(v).strip())
        except Exception:
            return None
        if minvalue is not None:
            n = max(int(minvalue), n)
        if maxvalue is not None:
            n = min(int(maxvalue), n)
        return n


