def paint_logo(p, rect, caret=1.0, shine=None):
    s = rect.width() / 256.0
    ox, oy = rect.x(), rect.y()
    small = rect.width() <= 24

    def P(x, y):
        return QPointF(ox + x * s, oy + y * s)

    p.save()
    p.setRenderHint(QPainter.RenderHint.Antialiasing, True)
    tile = QPainterPath()
    tile.addRoundedRect(QRectF(ox, oy, 256 * s, 256 * s), 58 * s, 58 * s)
    g = QLinearGradient(P(0, 0), P(0, 256))
    g.setColorAt(0.0, QColor("#2A323D"))
    g.setColorAt(1.0, QColor("#0E1217"))
    p.fillPath(tile, g)
    glow = QRadialGradient(P(128, 96), 150 * s)
    glow.setColorAt(0.0, QColor(242, 165, 58, 46))
    glow.setColorAt(1.0, QColor(242, 165, 58, 0))
    p.fillPath(tile, glow)
    if not small:
        p.setPen(QPen(QColor(255, 255, 255, 22), max(1.0, 3 * s)))
        p.setBrush(Qt.BrushStyle.NoBrush)
        inner = QPainterPath()
        inner.addRoundedRect(QRectF(ox + 1.5 * s, oy + 1.5 * s, 253 * s, 253 * s), 57 * s, 57 * s)
        p.drawPath(inner)
    k = 1.16 if rect.width() <= 32 else 1.0
    if k != 1.0:
        p.translate(ox + 128 * s, oy + 124 * s)
        p.scale(k, k)
        p.translate(-(ox + 128 * s), -(oy + 124 * s))
    bub = QPainterPath()
    bub.addRoundedRect(QRectF(ox + 46 * s, oy + 58 * s, 164 * s, 112 * s), 26 * s, 26 * s)
    tail = QPainterPath()
    tail.moveTo(P(76, 160))
    tail.lineTo(P(64, 206))
    tail.lineTo(P(118, 162))
    tail.closeSubpath()
    bub = bub.united(tail)
    bg = QLinearGradient(P(0, 58), P(0, 206))
    bg.setColorAt(0.0, QColor("#FFC66B"))
    bg.setColorAt(1.0, QColor("#EE8420"))
    p.setPen(Qt.PenStyle.NoPen)
    p.fillPath(bub, bg)
    if not small:
        hl = QLinearGradient(P(0, 58), P(0, 112))
        hl.setColorAt(0.0, QColor(255, 255, 255, 70))
        hl.setColorAt(1.0, QColor(255, 255, 255, 0))
        top = QPainterPath()
        top.addRoundedRect(QRectF(ox + 46 * s, oy + 58 * s, 164 * s, 54 * s), 26 * s, 26 * s)
        p.fillPath(top.intersected(bub), hl)
    if shine is not None and 0.0 < shine < 1.0:
        p.save()
        p.setClipPath(bub)
        x0 = -120 + shine * 420
        band = QPainterPath()
        band.moveTo(P(x0, 220))
        band.lineTo(P(x0 + 34, 220))
        band.lineTo(P(x0 + 120, 40))
        band.lineTo(P(x0 + 86, 40))
        band.closeSubpath()
        p.fillPath(band, QColor(255, 255, 255, 90))
        p.restore()
    ink = QColor("#151A20")
    w = (19 if small else 16) * s
    p.setPen(QPen(ink, w, Qt.PenStyle.SolidLine, Qt.PenCapStyle.RoundCap, Qt.PenJoinStyle.RoundJoin))
    chev = QPainterPath()
    chev.moveTo(P(84, 90))
    chev.lineTo(P(112, 114))
    chev.lineTo(P(84, 138))
    p.drawPath(chev)
    if caret > 0.02:
        c = QColor(ink)
        c.setAlphaF(max(0.0, min(1.0, caret)))
        p.setPen(QPen(c, w, Qt.PenStyle.SolidLine, Qt.PenCapStyle.RoundCap))
        p.drawLine(P(130, 138), P(170, 138))
    p.restore()


def app_icon_bytes():
    import base64 as _b64
    return _b64.b64decode("".join(_APP_ICON_B64.split()))


_APP_ICON = {"icon": None}


def app_icon():
    if _APP_ICON["icon"] is not None:
        return _APP_ICON["icon"]
    icon = QIcon()
    try:
        data = QByteArray(app_icon_bytes())
        buf = QBuffer(data)
        buf.open(QIODevice.OpenModeFlag.ReadOnly)
        reader = QImageReader(buf, b"ico")
        for _ in range(max(1, reader.imageCount())):
            img = reader.read()
            if not img.isNull():
                icon.addPixmap(QPixmap.fromImage(img))
            if not reader.jumpToNextImage():
                break
    except Exception as _ex:
        _trace(_ex_where(), _ex)
    if icon.isNull():
        for sz in (16, 24, 32, 48, 64, 128, 256):
            img = QImage(sz, sz, QImage.Format.Format_ARGB32_Premultiplied)
            img.fill(Qt.GlobalColor.transparent)
            pp = QPainter(img)
            paint_logo(pp, QRectF(0, 0, sz, sz))
            pp.end()
            icon.addPixmap(QPixmap.fromImage(img))
    _APP_ICON["icon"] = icon
    return icon


def write_app_icon_file():
    path = os.path.join(_appdir(), "yt2vm.ico")
    try:
        data = app_icon_bytes()
        if not os.path.exists(path) or os.path.getsize(path) != len(data):
            with open(path, "wb") as fh:
                fh.write(data)
    except Exception as _ex:
        _trace(_ex_where(), _ex)
    return path


def _win_app_id():
    if platform.system() != "Windows":
        return
    try:
        ctypes.windll.shell32.SetCurrentProcessExplicitAppUserModelID("ReallyIron.YT2VM")
    except Exception as _ex:
        _trace(_ex_where(), _ex)


def _win_titlebar(win, dark):
    if platform.system() != "Windows":
        return
    try:
        hwnd = int(win.winId())
        val = ctypes.c_int(1 if dark else 0)
        for attr in (20, 19):
            if ctypes.windll.dwmapi.DwmSetWindowAttribute(hwnd, attr, ctypes.byref(val), ctypes.sizeof(val)) == 0:
                break
        corner = ctypes.c_int(2)
        ctypes.windll.dwmapi.DwmSetWindowAttribute(hwnd, 33, ctypes.byref(corner), ctypes.sizeof(corner))
    except Exception as e:
        plog("UI", f"could not set title bar color: {e}")


