_ROLE_KEYS = ("hi", "text", "muted", "faint", "accent", "ok", "bad", "warn", "violet", "info", "on_accent")


def role_color(role):
    t = T()
    if role == "accent":
        return t["accent_text"]
    return t.get(role, t["text"])


def _role_for(fg):
    if fg in _ROLE_KEYS or fg.endswith("_soft"):
        return fg
    t = T()
    h = _hx(fg)
    if not h.startswith("#"):
        return None
    for r in ("hi", "text", "muted", "faint", "ok", "bad", "warn", "violet", "info"):
        if _hx(t[r]) == h:
            return r
    if _hx(t["accent_text"]) == h or _hx(t["accent"]) == h:
        return "accent"
    for r in ("ok", "bad", "warn", "violet", "info", "accent"):
        if _hx(t[r + "_soft"]) == h:
            return r + "_soft"
    try:
        return _studio_fg_role(h)
    except Exception:
        return None


class QtLabel(QLabel):
    def config(self, **kw):
        if "text" in kw:
            self.setText(str(kw["text"]))
        fg = kw.get("fg", kw.get("foreground"))
        if fg is not None:
            role = _role_for(str(fg))
            if role:
                if self.styleSheet():
                    self.setStyleSheet("")
                set_role(self, role)
            else:
                self.setStyleSheet(f"color:{fg};")
        if "font" in kw and isinstance(kw["font"], tuple) and kw["font"] and kw["font"][0] in ("ui", "mono", "display"):
            set_font(self, *kw["font"])
        if "wraplength" in kw:
            self.setWordWrap(bool(kw["wraplength"]))

    configure = config

    def cget(self, key):
        if key == "text":
            return self.text()
        return ""


def L(text="", role="text", font=("ui", 10), wrap=False, sel=False, align=None, parent=None):
    lab = QtLabel(str(text), parent)
    lab.setProperty("role", role)
    lab._qf = tuple(font)
    lab.setFont(QF(*font))
    if wrap:
        lab.setWordWrap(True)
    if sel:
        lab.setTextInteractionFlags(Qt.TextInteractionFlag.TextSelectableByMouse)
    if align is not None:
        lab.setAlignment(align)
    return lab


def set_role(lab, role):
    if lab.property("role") == role:
        return
    lab.setProperty("role", role)
    st = lab.style()
    st.unpolish(lab)
    st.polish(lab)
    lab.update()


def set_font(w, kind="ui", size=10, weight="normal"):
    w._qf = (kind, size, weight)
    w.setFont(QF(kind, size, weight))


def refont_all():
    for w in QApplication.allWidgets():
        spec = getattr(w, "_qf", None)
        if spec:
            try:
                w.setFont(QF(*spec))
            except RuntimeError:
                pass


def hbox(*items, spacing=8, margins=(0, 0, 0, 0), parent=None):
    lay = QHBoxLayout(parent)
    lay.setSpacing(spacing)
    lay.setContentsMargins(*margins)
    for it in items:
        _lay_add(lay, it)
    return lay


def vbox(*items, spacing=8, margins=(0, 0, 0, 0), parent=None):
    lay = QVBoxLayout(parent)
    lay.setSpacing(spacing)
    lay.setContentsMargins(*margins)
    for it in items:
        _lay_add(lay, it)
    return lay


def _lay_add(lay, it):
    if it is None:
        return
    if it == "stretch":
        lay.addStretch(1)
    elif isinstance(it, int):
        lay.addSpacing(it)
    elif isinstance(it, QLayout):
        lay.addLayout(it)
    else:
        lay.addWidget(it)


def row_widget(*items, spacing=8, margins=(0, 0, 0, 0)):
    w = QWidget()
    hbox(*items, spacing=spacing, margins=margins, parent=w)
    return w


class _HoverMixin:
    def _hover_init(self, key_in=130, key_out=240):
        self._hov = 0.0
        self._hov_in = key_in
        self._hov_out = key_out
        self._hov_anim = QVariantAnimation(self)
        self._hov_anim.valueChanged.connect(self._hov_set)
        self.setAttribute(Qt.WidgetAttribute.WA_Hover, True)

    def _hov_set(self, v):
        self._hov = float(v)
        self.update()

    def _hov_to(self, target):
        a = self._hov_anim
        a.stop()
        d = MOTION.ms(self._hov_in if target > self._hov else self._hov_out)
        if d <= 0:
            self._hov_set(target)
            return
        a.setStartValue(float(self._hov))
        a.setEndValue(float(target))
        a.setDuration(d)
        a.setEasingCurve(QEasingCurve(QEasingCurve.Type.OutCubic))
        a.start()

    def enterEvent(self, e):
        self._hov_to(1.0)
        super().enterEvent(e)

    def leaveEvent(self, e):
        self._hov_to(0.0)
        super().leaveEvent(e)


def _btn_palette(variant):
    t = T()
    if variant == "primary":
        return dict(bg=t["accent"], fg=t["on_accent"], border=t["accent"], hover=t["accent_hover"], glow=t["accent"])
    if variant == "ghost":
        return dict(bg=None, fg=t["text"], border=None, hover=mix(t["bg"], t["hi"], 0.06), glow=t["accent"])
    if variant == "link":
        return dict(bg=None, fg=t["accent_text"], border=None, hover=None, glow=t["accent"])
    sem = {"go": "ok", "danger": "bad", "warn": "warn", "soft": "accent", "info": "info", "violet": "violet"}.get(variant)
    if sem:
        return dict(bg=t[sem + "_tint"], fg=t[sem + "_soft"], border=t[sem + "_edge"],
                    hover=mix(t[sem + "_tint"], t[sem], 0.20), glow=t[sem])
    return dict(bg=t["raised"], fg=t["text"], border=t["line"], hover=t["raised_hover"], glow=t["accent"])


class Button(_HoverMixin, QAbstractButton):
    SIZES = {"sm": (30, 11, 9), "md": (36, 15, 10), "lg": (44, 20, 11)}

    def __init__(self, text="", command=None, variant="neutral", size="md", icon=None, parent=None, tip=None):
        super().__init__(parent)
        self._variant = variant
        self._size = size if size in self.SIZES else "md"
        self._icon = icon
        self._press = 0.0
        self._ripples = []
        self._busy = False
        self._spin = 0.0
        self.setText(str(text))
        self.setCursor(Qt.CursorShape.PointingHandCursor)
        self.setFocusPolicy(Qt.FocusPolicy.StrongFocus)
        self._qf = ("ui", self.SIZES[self._size][2], "semi")
        self.setFont(QF(*self._qf))
        self._hover_init()
        self._press_anim = QVariantAnimation(self)
        self._press_anim.valueChanged.connect(self._set_press)
        self._rip_timer = QTimer(self)
        self._rip_timer.timeout.connect(self._rip_tick)
        if command is not None:
            self.clicked.connect(lambda *_: command())
        if tip:
            self.setToolTip(tip)
        self.setSizePolicy(QSizePolicy.Policy.Preferred, QSizePolicy.Policy.Fixed)

    def variant(self):
        return self._variant

    def setVariant(self, v):
        self._variant = v
        self.update()

    def setIcon(self, name):
        self._icon = name
        self.updateGeometry()
        self.update()

    def set_busy(self, on):
        self._busy = bool(on)
        self.setEnabled(not on)
        if on:
            MOTION.loop(("btnspin", id(self)), self._spin_frame, 900, fps=40)
        else:
            MOTION.unloop(("btnspin", id(self)), rest=False)
        self.update()

    def _spin_frame(self, ph):
        self._spin = ph
        self.update()

    def config(self, **kw):
        if "text" in kw:
            self.setText(str(kw["text"]))
        if "state" in kw:
            self.setEnabled(kw["state"] != "disabled")
        if "variant" in kw:
            self.setVariant(kw["variant"])

    configure = config

    def cget(self, key):
        return self.text() if key == "text" else ""

    def sizeHint(self):
        h, padx, _ = self.SIZES[self._size]
        fm = QFontMetrics(self.font())
        w = fm.horizontalAdvance(self.text()) + padx * 2
        if self._icon:
            w += int(h * 0.42) + (8 if self.text() else 0)
        return QSize(max(w, h), h)

    def minimumSizeHint(self):
        h = self.SIZES[self._size][0]
        return QSize(h, h)

    def _set_press(self, v):
        self._press = float(v)
        self.update()

    def _press_to(self, target, ms):
        a = self._press_anim
        a.stop()
        d = MOTION.ms(ms)
        if d <= 0:
            self._set_press(target)
            return
        a.setStartValue(self._press)
        a.setEndValue(float(target))
        a.setDuration(d)
        a.setEasingCurve(QEasingCurve(QEasingCurve.Type.OutCubic))
        a.start()

    def mousePressEvent(self, e):
        if e.button() == Qt.MouseButton.LeftButton:
            self._press_to(1.0, 90)
            if MOTION.on:
                self._ripples.append([e.position(), time.perf_counter()])
                if not self._rip_timer.isActive():
                    self._rip_timer.start(16)
        super().mousePressEvent(e)

    def mouseReleaseEvent(self, e):
        self._press_to(0.0, 260)
        super().mouseReleaseEvent(e)

    def _rip_tick(self):
        now = time.perf_counter()
        self._ripples = [r for r in self._ripples if now - r[1] < 0.55]
        if not self._ripples:
            self._rip_timer.stop()
        self.update()

    def paintEvent(self, ev):
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing, True)
        pal = _btn_palette(self._variant)
        r = QRectF(self.rect()).adjusted(0.5, 0.5, -0.5, -0.5)
        k = 1.0 - 0.035 * self._press
        p.translate(r.center())
        p.scale(k, k)
        p.translate(-r.center())
        rad = min(10.0, r.height() / 2.0 - 1)
        en = self.isEnabled()
        if not en:
            p.setOpacity(0.45 if not self._busy else 0.85)
        path = QPainterPath()
        path.addRoundedRect(r, rad, rad)
        if pal["bg"] is not None or pal["hover"] is not None:
            base = pal["bg"] if pal["bg"] is not None else T()["bg"]
            if pal["bg"] is None:
                col = qc(pal["hover"], self._hov) if pal["hover"] else None
                if col is not None:
                    p.fillPath(path, col)
            else:
                fill = mix(base, pal["hover"], self._hov) if pal["hover"] else base
                if self._variant == "primary":
                    g = QLinearGradient(r.topLeft(), r.bottomLeft())
                    g.setColorAt(0.0, qc(mix(fill, "#FFFFFF", 0.10)))
                    g.setColorAt(1.0, qc(fill))
                    p.fillPath(path, g)
                else:
                    p.fillPath(path, qc(fill))
        if pal["border"] is not None:
            edge = mix(pal["border"], pal["glow"], 0.45 * self._hov) if self._variant != "primary" else pal["border"]
            p.setPen(QPen(qc(edge), 1.0))
            p.drawPath(path)
        if self._ripples:
            p.save()
            p.setClipPath(path)
            now = time.perf_counter()
            for pos, born in self._ripples:
                f = (now - born) / 0.55
                rr = 6 + f * max(r.width(), r.height()) * 1.15
                c = qc("#FFFFFF" if T()["dark"] or self._variant == "primary" else "#000000", 0.16 * (1.0 - f))
                p.setPen(Qt.PenStyle.NoPen)
                p.setBrush(c)
                p.drawEllipse(pos, rr, rr)
            p.restore()
        if self.hasFocus() and self.isEnabled() and getattr(self, "_kbd_focus", False):
            p.setPen(QPen(qc(T()["accent"], 0.85), 2.0))
            p.setBrush(Qt.BrushStyle.NoBrush)
            p.drawRoundedRect(r.adjusted(-1.5, -1.5, 1.5, 1.5), rad + 1.5, rad + 1.5)
        fg = qc(pal["fg"])
        if self._variant == "link":
            fg = qc(mix(pal["fg"], T()["hi"], 0.35 * self._hov))
        p.setPen(fg)
        p.setFont(self.font())
        fm = QFontMetrics(self.font())
        tw = fm.horizontalAdvance(self.text())
        isz = r.height() * 0.42 if (self._icon or self._busy) else 0
        gap = 8 if (isz and self.text()) else 0
        total = tw + isz + gap
        x = r.center().x() - total / 2.0
        if self._busy:
            p.save()
            pen = QPen(fg, 2.0, Qt.PenStyle.SolidLine, Qt.PenCapStyle.RoundCap)
            p.setPen(pen)
            rect = QRectF(x, r.center().y() - isz / 2.0, isz, isz)
            p.drawArc(rect, int(-self._spin * 360 * 16), int(270 * 16))
            p.restore()
            x += isz + gap
        elif self._icon:
            draw_icon(p, self._icon, QRectF(x, r.center().y() - isz / 2.0, isz, isz), fg, w=max(1.4, isz / 9.0))
            x += isz + gap
        p.setPen(fg)
        p.drawText(QRectF(x, r.y(), tw + 2, r.height()), int(Qt.AlignmentFlag.AlignVCenter | Qt.AlignmentFlag.AlignLeft), self.text())
        p.end()

    def focusInEvent(self, e):
        self._kbd_focus = e.reason() in (Qt.FocusReason.TabFocusReason, Qt.FocusReason.BacktabFocusReason)
        super().focusInEvent(e)

    def focusOutEvent(self, e):
        self._kbd_focus = False
        super().focusOutEvent(e)

    def keyPressEvent(self, e):
        if e.key() in (Qt.Key.Key_Return, Qt.Key.Key_Enter):
            self.click()
            return
        super().keyPressEvent(e)


class IconButton(_HoverMixin, QAbstractButton):
    def __init__(self, icon, command=None, tip="", size=34, parent=None, round_=True):
        super().__init__(parent)
        self._icon = icon
        self._sz = size
        self._round = round_
        self._active = 0.0
        self.setCursor(Qt.CursorShape.PointingHandCursor)
        self.setFixedSize(size, size)
        self.setToolTip(tip)
        self._hover_init()
        if command is not None:
            self.clicked.connect(lambda *_: command())

    def setIcon(self, name):
        self._icon = name
        self.update()

    def paintEvent(self, ev):
        t = T()
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing, True)
        r = QRectF(self.rect()).adjusted(1, 1, -1, -1)
        if self._hov > 0.01 or self.isDown():
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(qc(mix(t["bg"], t["hi"], 0.09 if self.isDown() else 0.06), min(1.0, self._hov + (0.4 if self.isDown() else 0))))
            if self._round:
                p.drawEllipse(r)
            else:
                p.drawRoundedRect(r, 9, 9)
        col = mix(t["muted"], t["hi"], self._hov)
        isz = self._sz * 0.5
        draw_icon(p, self._icon, QRectF(r.center().x() - isz / 2, r.center().y() - isz / 2, isz, isz), qc(col), w=1.6)
        p.end()


class Toggle(_HoverMixin, QAbstractButton):
    def __init__(self, text="", value=False, command=None, parent=None):
        super().__init__(parent)
        self.setCheckable(True)
        self.setChecked(bool(value))
        self.setText(str(text))
        self._pos = 1.0 if value else 0.0
        self._qf = ("ui", 10)
        self.setFont(QF(*self._qf))
        self.setCursor(Qt.CursorShape.PointingHandCursor)
        self._hover_init()
        self._anim = QVariantAnimation(self)
        self._anim.valueChanged.connect(self._set_pos)
        self.toggled.connect(self._animate)
        if command is not None:
            self.clicked.connect(lambda *_: command())
        self.setSizePolicy(QSizePolicy.Policy.Preferred, QSizePolicy.Policy.Fixed)

    def get(self):
        return self.isChecked()

    def set(self, v):
        self.setChecked(bool(v))

    def _set_pos(self, v):
        self._pos = float(v)
        self.update()

    def _animate(self, on):
        a = self._anim
        a.stop()
        d = MOTION.ms(260)
        if d <= 0:
            self._set_pos(1.0 if on else 0.0)
            return
        a.setStartValue(self._pos)
        a.setEndValue(1.0 if on else 0.0)
        a.setDuration(d)
        c = QEasingCurve(QEasingCurve.Type.OutBack)
        c.setOvershoot(1.2)
        a.setEasingCurve(c)
        a.start()

    def sizeHint(self):
        fm = QFontMetrics(self.font())
        return QSize(40 + (12 + fm.horizontalAdvance(self.text()) if self.text() else 0), max(26, fm.height() + 6))

    def hitButton(self, pos):
        return self.rect().contains(pos)

    def paintEvent(self, ev):
        t = T()
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing, True)
        if not self.isEnabled():
            p.setOpacity(0.45)
        h = 22.0
        w = 40.0
        y = (self.height() - h) / 2.0
        track = QRectF(0.5, y, w, h)
        pos = max(0.0, min(1.0, self._pos))
        off = mix(t["raised"], t["line"], 0.4 + 0.3 * self._hov)
        on = t["accent"]
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(qc(mix(off, on, pos)))
        p.drawRoundedRect(track, h / 2, h / 2)
        kr = h - 6
        kx = track.x() + 3 + (w - kr - 6) * self._pos
        p.setBrush(qc(0x000000, 0.18))
        p.drawEllipse(QRectF(kx, y + 4, kr, kr))
        p.setBrush(qc(mix("#FFFFFF", t["on_accent"] if _lum(t["accent"]) > 0.6 else "#FFFFFF", 0.0)))
        grow = 1.5 * self._hov
        p.drawEllipse(QRectF(kx - grow / 2, y + 3 - grow / 2, kr + grow, kr + grow))
        if self.text():
            p.setPen(qc(t["text"] if not self.isChecked() else t["hi"]))
            p.setFont(self.font())
            p.drawText(QRectF(w + 12, 0, self.width() - w - 12, self.height()),
                       int(Qt.AlignmentFlag.AlignVCenter | Qt.AlignmentFlag.AlignLeft), self.text())
        p.end()


class Card(_HoverMixin, QFrame):
    def __init__(self, title=None, subtitle=None, parent=None, pad=18, glow=True, tint=None):
        super().__init__(parent)
        self._glow = glow
        self._tint = tint
        self.setAttribute(Qt.WidgetAttribute.WA_StyledBackground, False)
        self._hover_init(180, 320)
        outer = QVBoxLayout(self)
        outer.setContentsMargins(pad, pad - 2 if title else pad, pad, pad)
        outer.setSpacing(10)
        self.head = None
        self.actions = None
        if title:
            head = QHBoxLayout()
            head.setSpacing(10)
            tl = QVBoxLayout()
            tl.setSpacing(2)
            self.title_lbl = L(title, "hi", ("display", 12.5))
            tl.addWidget(self.title_lbl)
            if subtitle:
                self.sub_lbl = L(subtitle, "muted", ("ui", 9), wrap=True)
                tl.addWidget(self.sub_lbl)
            head.addLayout(tl, 1)
            self.actions = QHBoxLayout()
            self.actions.setSpacing(8)
            head.addLayout(self.actions)
            outer.addLayout(head)
            self.head = head
        self.body = QVBoxLayout()
        self.body.setSpacing(10)
        self.body.setContentsMargins(0, 2 if title else 0, 0, 0)
        outer.addLayout(self.body, 1)

    def add(self, *items):
        for it in items:
            _lay_add(self.body, it)
        return self

    def add_action(self, w):
        if self.actions is not None:
            self.actions.addWidget(w)
        return w

    def paintEvent(self, ev):
        t = T()
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing, True)
        r = QRectF(self.rect()).adjusted(0.5, 0.5, -0.5, -0.5)
        path = QPainterPath()
        path.addRoundedRect(r, 14, 14)
        base = t["card"] if not self._tint else mix(t["card"], t[self._tint], 0.10 if t["dark"] else 0.07)
        g = QLinearGradient(r.topLeft(), r.bottomLeft())
        g.setColorAt(0.0, qc(mix(base, t["hi"], 0.025 if t["dark"] else 0.0)))
        g.setColorAt(1.0, qc(base))
        p.fillPath(path, g)
        edge = t["line"] if not self._tint else t[self._tint + "_edge"]
        if self._glow:
            edge = mix(edge, t["accent"], 0.42 * self._hov)
        p.setPen(QPen(qc(edge), 1.0))
        p.drawPath(path)
        if t["dark"]:
            p.setPen(QPen(qc("#FFFFFF", 0.035), 1.0))
            p.drawLine(QPointF(r.left() + 14, r.top() + 1), QPointF(r.right() - 14, r.top() + 1))
        p.end()


