class LineEdit(QLineEdit):
    def __init__(self, text="", placeholder="", mono=False, secret=False, parent=None, on_enter=None, width=None, align=None):
        super().__init__(parent)
        self._qf = ("mono", 10.5) if mono else ("ui", 10)
        self.setFont(QF(*self._qf))
        if text:
            self.setText(str(text))
        if placeholder:
            self.setPlaceholderText(placeholder)
        if secret:
            self.setEchoMode(QLineEdit.EchoMode.Password)
        if on_enter is not None:
            self.returnPressed.connect(lambda *_: on_enter())
        if width:
            self.setFixedWidth(int(width))
        if align == "center":
            self.setAlignment(Qt.AlignmentFlag.AlignCenter)
        self.setMinimumHeight(36)

    def get(self):
        return self.text()

    def set(self, v):
        self.setText(str(v))

    def delete(self, first=0, last=None):
        if first in (0, "0") and last in (None, "end", "END"):
            self.clear()
            return
        try:
            a = 0 if first in (0, "0") else int(first)
            b = len(self.text()) if last in (None, "end", "END") else int(last)
            t = self.text()
            self.setText(t[:a] + t[b:])
        except Exception:
            self.clear()

    def insert(self, idx, text=None):
        if text is None:
            text, idx = idx, "end"
        text = str(text)
        cur = self.text()
        if idx in ("end", "END", "insert"):
            self.setText(cur + text)
        else:
            try:
                i = int(idx)
            except Exception:
                i = len(cur)
            self.setText(cur[:i] + text + cur[i:])

    def icursor(self, idx):
        self.setCursorPosition(len(self.text()) if idx in ("end", "END") else int(idx))

    def focus_set(self):
        self.setFocus()


class Combo(QComboBox):
    def __init__(self, values=(), value=None, editable=False, parent=None, on_change=None, width=None):
        super().__init__(parent)
        self._qf = ("ui", 10)
        self.setFont(QF(*self._qf))
        self.setEditable(bool(editable))
        if editable:
            self.lineEdit().setFont(QF(*self._qf))
        self.set_values(values)
        if value is not None:
            self.set(value)
        if on_change is not None:
            self.textActivated.connect(lambda *_: on_change())
        if width:
            self.setMinimumWidth(int(width))
        self.setMinimumHeight(36)
        self.setCursor(Qt.CursorShape.PointingHandCursor)
        v = self.view()
        v.setFont(QF("ui", 10))

    def get(self):
        return self.currentText()

    def set(self, v):
        v = str(v)
        i = self.findText(v)
        if i >= 0:
            self.setCurrentIndex(i)
        elif self.isEditable():
            self.setEditText(v)
        elif v == "" and self.count():
            self.setCurrentIndex(-1)

    def set_values(self, values):
        cur = self.currentText()
        self.blockSignals(True)
        self.clear()
        self.addItems([str(x) for x in values])
        i = self.findText(cur)
        if i >= 0:
            self.setCurrentIndex(i)
        self.blockSignals(False)

    def values(self):
        return [self.itemText(i) for i in range(self.count())]

    def __getitem__(self, key):
        if key == "values":
            return tuple(self.values())
        raise KeyError(key)

    def __setitem__(self, key, val):
        if key == "values":
            cur = self.currentText()
            self.set_values(list(val or ()))
            if self.isEditable():
                self.setEditText(cur)
        else:
            raise KeyError(key)

    def config(self, **kw):
        if "values" in kw:
            self["values"] = kw["values"]
        if "state" in kw:
            self.setEnabled(kw["state"] != "disabled")

    configure = config

    def current(self, i=None):
        if i is None:
            return self.currentIndex()
        self.setCurrentIndex(int(i))

    def paintEvent(self, ev):
        super().paintEvent(ev)
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing, True)
        t = T()
        cx = self.width() - 16
        cy = self.height() / 2.0 + 1
        p.setPen(QPen(qc(t["muted"]), 1.6, Qt.PenStyle.SolidLine, Qt.PenCapStyle.RoundCap, Qt.PenJoinStyle.RoundJoin))
        path = QPainterPath(QPointF(cx - 4.5, cy - 2.5))
        path.lineTo(QPointF(cx, cy + 2.2))
        path.lineTo(QPointF(cx + 4.5, cy - 2.5))
        p.drawPath(path)
        p.end()


