class SmoothScroll(QScrollArea):
    def __init__(self, parent=None, margins=(28, 22, 28, 28), spacing=14):
        super().__init__(parent)
        self.setWidgetResizable(True)
        self.setFrameShape(QFrame.Shape.NoFrame)
        self.setHorizontalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAlwaysOff)
        self.inner = QWidget()
        self.inner.setObjectName("PageHost")
        self.body = QVBoxLayout(self.inner)
        self.body.setContentsMargins(*margins)
        self.body.setSpacing(spacing)
        self.setWidget(self.inner)
        self._target = None
        self._anim = QPropertyAnimation(self.verticalScrollBar(), b"value", self)
        self._anim.setEasingCurve(QEasingCurve(QEasingCurve.Type.OutCubic))
        self._anim.finished.connect(self._done)

    def _done(self):
        self._target = None

    def add(self, *items):
        for it in items:
            _lay_add(self.body, it)
        return self

    def wheelEvent(self, e):
        if not MOTION.on or e.modifiers() & Qt.KeyboardModifier.ControlModifier:
            return super().wheelEvent(e)
        if not e.pixelDelta().isNull() and abs(e.pixelDelta().y()) > 0:
            return super().wheelEvent(e)
        dy = e.angleDelta().y()
        if dy == 0:
            return super().wheelEvent(e)
        sb = self.verticalScrollBar()
        base = self._target if self._target is not None else sb.value()
        step = -dy / 120.0 * 92
        tgt = int(max(sb.minimum(), min(sb.maximum(), base + step)))
        self._target = tgt
        self._anim.stop()
        self._anim.setStartValue(sb.value())
        self._anim.setEndValue(tgt)
        self._anim.setDuration(MOTION.ms(240))
        self._anim.start()
        e.accept()


class FormGrid(QGridLayout):
    def __init__(self, parent=None, label_w=None):
        super().__init__(parent)
        self.setHorizontalSpacing(16)
        self.setVerticalSpacing(10)
        self.setColumnStretch(1, 1)
        self._row = 0
        self._lw = label_w

    def field(self, label, widget, hint=None):
        lab = L(label, "muted", ("ui", 9.5, "medium"))
        if self._lw:
            lab.setMinimumWidth(self._lw)
        self.addWidget(lab, self._row, 0, Qt.AlignmentFlag.AlignVCenter)
        if isinstance(widget, QLayout):
            self.addLayout(widget, self._row, 1)
        else:
            self.addWidget(widget, self._row, 1)
        self._row += 1
        if hint:
            self.addWidget(L(hint, "faint", ("ui", 8.5), wrap=True), self._row, 1)
            self._row += 1
        return widget

    def full(self, widget):
        if isinstance(widget, QLayout):
            self.addLayout(widget, self._row, 0, 1, 2)
        else:
            self.addWidget(widget, self._row, 0, 1, 2)
        self._row += 1
        return widget


class ModernDialog(QDialog):
    def __init__(self, parent, title, message, kind="info", buttons=(("OK", True, "primary"),), field=None, secret=False,
                 width=460, extra=None):
        super().__init__(parent)
        self.setWindowFlags(Qt.WindowType.Dialog | Qt.WindowType.FramelessWindowHint)
        self.setAttribute(Qt.WidgetAttribute.WA_TranslucentBackground, True)
        self.setModal(True)
        self.setWindowTitle(title)
        self._result = None
        self.field_value = None
        self._kind = kind
        self._scale = 0.94
        self._opa = 0.0
        outer = QVBoxLayout(self)
        outer.setContentsMargins(24, 24, 24, 24)
        self.panel = QWidget()
        self.panel.setObjectName("DlgPanel")
        self.panel.paintEvent = self._paint_panel
        outer.addWidget(self.panel)
        lay = QVBoxLayout(self.panel)
        lay.setContentsMargins(24, 22, 24, 20)
        lay.setSpacing(12)
        head = QHBoxLayout()
        head.setSpacing(12)
        self._icon = QWidget()
        self._icon.setFixedSize(34, 34)
        self._icon.paintEvent = self._paint_icon
        head.addWidget(self._icon, 0, Qt.AlignmentFlag.AlignTop)
        tl = L(title, "hi", ("display", 13.5), wrap=True)
        head.addWidget(tl, 1)
        lay.addLayout(head)
        if message:
            ml = L(message, "text", ("ui", 10), wrap=True, sel=True)
            ml.setMinimumWidth(width - 120)
            lay.addWidget(ml)
        if extra is not None:
            lay.addWidget(extra)
        self.edit = None
        if field is not None:
            self.edit = LineEdit(field, secret=secret)
            self.edit.returnPressed.connect(self._accept_default)
            lay.addWidget(self.edit)
        brow = QHBoxLayout()
        brow.addStretch(1)
        self._default = None
        for text, val, var in buttons:
            b = Button(text, variant=var)
            b.setMinimumWidth(92)
            b.clicked.connect(lambda *_, v=val: self._finish(v))
            brow.addWidget(b)
            if var == "primary":
                self._default = (b, val)
        lay.addSpacing(4)
        lay.addLayout(brow)
        self.setMinimumWidth(width)
        sh = QGraphicsDropShadowEffect(self.panel)
        sh.setBlurRadius(42)
        sh.setOffset(0, 10)
        sh.setColor(QColor(0, 0, 0, 150))
        self.panel.setGraphicsEffect(sh)

    def _accept_default(self):
        if self._default is not None:
            self._finish(self._default[1])

    def _finish(self, val):
        self._result = val
        if self.edit is not None:
            self.field_value = self.edit.text()
        self.done(1 if val else 0)

    def keyPressEvent(self, e):
        if e.key() == Qt.Key.Key_Escape:
            self._result = None
            self.done(0)
            return
        if e.key() in (Qt.Key.Key_Return, Qt.Key.Key_Enter) and self.edit is None:
            self._accept_default()
            return
        super().keyPressEvent(e)

    def _paint_panel(self, ev):
        t = T()
        p = QPainter(self.panel)
        p.setRenderHint(QPainter.RenderHint.Antialiasing, True)
        r = QRectF(self.panel.rect()).adjusted(0.5, 0.5, -0.5, -0.5)
        p.setPen(QPen(qc(t["line"]), 1.0))
        p.setBrush(qc(t["panel"]))
        p.drawRoundedRect(r, 16, 16)
        col = {"bad": t["bad"], "warn": t["warn"], "ask": t["accent"], "ok": t["ok"]}.get(self._kind, t["info"])
        g = QLinearGradient(r.topLeft(), QPointF(r.left(), r.top() + 70))
        c1 = qc(col, 0.10)
        c2 = qc(col, 0.0)
        g.setColorAt(0.0, c1)
        g.setColorAt(1.0, c2)
        path = QPainterPath()
        path.addRoundedRect(r, 16, 16)
        p.fillPath(path, g)
        p.end()

    def _paint_icon(self, ev):
        t = T()
        p = QPainter(self._icon)
        p.setRenderHint(QPainter.RenderHint.Antialiasing, True)
        col = {"bad": t["bad"], "warn": t["warn"], "ask": t["accent"], "ok": t["ok"]}.get(self._kind, t["info"])
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(qc(col, 0.16))
        p.drawRoundedRect(QRectF(0, 0, 34, 34), 10, 10)
        name = {"bad": "close", "warn": "sparkle", "ask": "help", "ok": "check"}.get(self._kind, "help")
        draw_icon(p, name, QRectF(8, 8, 18, 18), qc(col), w=2.0)
        p.end()

    def showEvent(self, e):
        super().showEvent(e)
        par = self.parentWidget()
        if par is not None:
            g = par.window().geometry()
            self.adjustSize()
            self.move(g.center().x() - self.width() // 2, g.center().y() - self.height() // 2 - 30)
        if MOTION.on:
            self.setWindowOpacity(0.0)
            MOTION.tween(("dlg", id(self)), 220, lambda v: self.setWindowOpacity(v), 1.0, a=0.0, ease="out")
        if self.edit is not None:
            QTimer.singleShot(30, self.edit.setFocus)
        elif self._default is not None:
            QTimer.singleShot(30, self._default[0].setFocus)

    def run(self):
        self.exec()
        return self._result


class QtVar:
    def __init__(self, value=None):
        self._v = value
        self._cbs = []

    def get(self):
        return self._v

    def set(self, v):
        if v == self._v:
            return
        self._v = v
        for cb in list(self._cbs):
            try:
                cb(v)
            except Exception as _ex:
                _trace(_ex_where(), _ex)

    def on_change(self, cb):
        self._cbs.append(cb)
        return cb


class TkText(QPlainTextEdit):
    def __init__(self, parent=None, mono=True, size=9.5, max_lines=4000, height=None, wrap=True):
        super().__init__(parent)
        self.setReadOnly(True)
        self._qf = ("mono", size) if mono else ("ui", size + 0.5)
        self.setFont(QF(*self._qf))
        self.setMaximumBlockCount(max_lines)
        self.setLineWrapMode(QPlainTextEdit.LineWrapMode.WidgetWidth if wrap else QPlainTextEdit.LineWrapMode.NoWrap)
        self._tags = {}
        self._hidden = set()
        if height:
            self.setMinimumHeight(int(height))

    def configure(self, **kw):
        if "state" in kw:
            self.setReadOnly(kw["state"] == "disabled")

    config = configure

    def tag_config(self, tag, **kw):
        cur = dict(self._tags.get(tag, {}))
        cur.update(kw)
        self._tags[tag] = cur

    tag_configure = tag_config

    def _fmt(self, tags):
        fmt = QTextCharFormat()
        if isinstance(tags, str):
            tags = (tags,)
        for tg in tags or ():
            spec = self._tags.get(tg) or {}
            fg = spec.get("foreground") or spec.get("fg")
            if fg:
                fmt.setForeground(qc(role_color(fg) if fg in _ROLE_KEYS else fg))
            bg = spec.get("background")
            if bg:
                fmt.setBackground(qc(role_color(bg) if bg in _ROLE_KEYS else bg))
            fnt = spec.get("font")
            if isinstance(fnt, tuple) and any(str(x).lower() == "bold" for x in fnt[1:]):
                fmt.setFontWeight(QFont.Weight.DemiBold)
        return fmt

    def insert(self, idx, text, tags=()):
        cur = QTextCursor(self.document())
        cur.movePosition(QTextCursor.MoveOperation.End)
        cur.insertText(str(text), self._fmt(tags))

    def delete(self, *a):
        self.clear()

    def get(self, *a):
        return self.toPlainText()

    def see(self, idx="end"):
        sb = self.verticalScrollBar()
        if idx in ("end", "END"):
            sb.setValue(sb.maximum())
        else:
            sb.setValue(0)

    def index(self, idx):
        if idx in ("end-1c", "end"):
            return f"{self.document().blockCount()}.0"
        return "1.0"

    def yview_moveto(self, f):
        sb = self.verticalScrollBar()
        sb.setValue(int(sb.maximum() * float(f)))


