class NavItem(_HoverMixin, QWidget):
    clicked = pyqtSignal()

    def __init__(self, label, parent=None):
        super().__init__(parent)
        self.label = label
        self.icon = _PAGE_ICONS.get(label, "sparkle")
        self.badge = ""
        self._act = 0.0
        self._intro = 1.0
        self._badge_flash = 0.0
        self.setFixedHeight(36)
        self.setCursor(Qt.CursorShape.PointingHandCursor)
        self._hover_init(90, 200)
        self._aa = QVariantAnimation(self)
        self._aa.valueChanged.connect(self._set_act)

    def set_active(self, on, animate=True):
        target = 1.0 if on else 0.0
        a = self._aa
        a.stop()
        d = MOTION.ms(230) if animate else 0
        if d <= 0:
            self._set_act(target)
            return
        a.setStartValue(self._act)
        a.setEndValue(target)
        a.setDuration(d)
        a.setEasingCurve(QEasingCurve(QEasingCurve.Type.OutCubic))
        a.start()

    def _set_act(self, v):
        self._act = float(v)
        self.update()

    def set_intro(self, v):
        self._intro = float(v)
        self.update()

    def set_badge(self, text):
        text = str(text or "")
        if text == self.badge:
            return
        grew = bool(text) and text != self.badge
        self.badge = text
        if grew:
            MOTION.tween(("navbadge", id(self)), 900, self._set_bflash, 0.0, a=1.0)
        self.update()

    def _set_bflash(self, v):
        self._badge_flash = v
        self.update()

    def mousePressEvent(self, e):
        if e.button() == Qt.MouseButton.LeftButton:
            self.clicked.emit()

    def paintEvent(self, ev):
        t = T()
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing, True)
        side = t["side"]
        intro = max(0.0, min(1.0, self._intro))
        dx = 18 * (1.0 - intro)
        p.setOpacity(intro)
        r = QRectF(10 + dx, 1, self.width() - 22, self.height() - 2)
        act = self._act
        bg = mix(mix(side, t["hi"], 0.05 * self._hov), mix(side, t["accent"], 0.13), act)
        if act > 0.01 or self._hov > 0.01:
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(qc(bg))
            p.drawRoundedRect(r, 9, 9)
        fg = mix(mix(t["muted"], t["hi"], self._hov), t["hi"], act)
        icol = mix(mix(t["faint"], t["text"], self._hov), t["accent_text"], act)
        draw_icon(p, self.icon, QRectF(r.x() + 12, r.center().y() - 8.5, 17, 17), qc(icol), w=1.45)
        f = QF("ui", 10, "semi" if act > 0.5 else "normal")
        p.setFont(f)
        p.setPen(qc(fg))
        tx = r.x() + 39
        bw = 0
        if self.badge:
            bf = QF("ui", 8, "semi")
            bw = QFontMetrics(bf).horizontalAdvance(self.badge) + 14
        p.drawText(QRectF(tx, r.y(), r.width() - (tx - r.x()) - bw - 10, r.height()),
                   int(Qt.AlignmentFlag.AlignVCenter | Qt.AlignmentFlag.AlignLeft), self.label)
        if self.badge:
            bf = QF("ui", 8, "semi")
            p.setFont(bf)
            br = QRectF(r.right() - bw - 8, r.center().y() - 9, bw, 18)
            bbg = mix(mix(bg, t["hi"], 0.09), t["accent"], self._badge_flash)
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(qc(bbg))
            p.drawRoundedRect(br, 9, 9)
            p.setPen(qc(mix(t["text"], t["on_accent"], self._badge_flash)))
            p.drawText(br, int(Qt.AlignmentFlag.AlignCenter), self.badge)
        p.end()


