class ActivityCard(QWidget):
    def __init__(self, parent=None):
        super().__init__(parent)
        self._busy = False
        self._ph = 0.0
        self._key = None
        lay = QVBoxLayout(self)
        lay.setContentsMargins(14, 12, 14, 12)
        lay.setSpacing(3)
        head = QHBoxLayout()
        head.setSpacing(6)
        self.dot = Dot("faint", 8)
        head.addWidget(self.dot)
        self.title = L("Executor idle", "muted", ("ui", 8.5, "semi"))
        head.addWidget(self.title, 1)
        lay.addLayout(head)
        self.cmd = L("Nothing running", "faint", ("mono", 9))
        self.cmd.setWordWrap(True)
        lay.addWidget(self.cmd)
        self.bar = QWidget()
        self.bar.setFixedHeight(3)
        self.bar.paintEvent = self._paint_bar
        lay.addWidget(self.bar)
        self.sub = L("Queue 0", "faint", ("ui", 8.5))
        lay.addWidget(self.sub)

    def set_activity(self, current, queued, waiting=0):
        cur = (current or "").strip()
        key = (cur, queued, waiting)
        if key == self._key:
            return
        self._key = key
        busy = bool(cur)
        self.title.setText("Executing" if busy else "Executor idle")
        self.cmd.setText((cur if len(cur) <= 60 else cur[:57] + "...") if busy else "Nothing running")
        set_role(self.cmd, "hi" if busy else "faint")
        self.sub.setText(f"Queue {queued}" + (f"  /  {waiting} viewer{'s' if waiting != 1 else ''} waiting" if waiting else ""))
        self.dot.set("ok" if busy else "faint", pulse=busy)
        if busy != self._busy:
            self._busy = busy
            if busy:
                MOTION.loop(("exec", id(self)), self._frame, 1400, fps=40)
            else:
                MOTION.unloop(("exec", id(self)), rest=False)
                self._ph = 0.0
                self.bar.update()

    def _frame(self, ph):
        self._ph = ph
        self.bar.update()

    def _paint_bar(self, ev):
        t = T()
        p = QPainter(self.bar)
        p.setRenderHint(QPainter.RenderHint.Antialiasing, True)
        w = self.bar.width()
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(qc(t["raised"]))
        p.drawRoundedRect(QRectF(0, 0, w, 3), 1.5, 1.5)
        if self._busy:
            seg = w * 0.38
            e = QEasingCurve(QEasingCurve.Type.InOutCubic).valueForProgress(self._ph)
            x = -seg + e * (w + seg)
            g = QLinearGradient(x, 0, x + seg, 0)
            c0 = qc(t["ok"], 0.0)
            c1 = qc(t["ok"], 1.0)
            g.setColorAt(0.0, c0)
            g.setColorAt(0.5, c1)
            g.setColorAt(1.0, c0)
            p.setBrush(g)
            p.drawRoundedRect(QRectF(max(0, x), 0, min(w, x + seg) - max(0, x), 3), 1.5, 1.5)
        p.end()

    def paintEvent(self, ev):
        t = T()
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing, True)
        r = QRectF(self.rect()).adjusted(0.5, 0.5, -0.5, -0.5)
        p.setPen(QPen(qc(t["line"]), 1.0))
        p.setBrush(qc(t["card"]))
        p.drawRoundedRect(r, 12, 12)
        p.end()


