class Toast(QWidget):
    def __init__(self, host, text, kind, life_ms, mgr=None):
        super().__init__(host)
        self.host = host
        self.mgr = mgr
        self.text = str(text)
        self.kind = kind
        self.born = time.time()
        self.life = life_ms
        self.frac = 1.0
        self.off = 1.0
        self._paused = False
        self.setFixedWidth(360)
        self.setCursor(Qt.CursorShape.PointingHandCursor)
        lay = QVBoxLayout(self)
        lay.setContentsMargins(18, 11, 14, 12)
        lay.setSpacing(2)
        ttl = {"bad": "Error", "warn": "Warning", "ok": "Done"}.get(kind, "Notice")
        self.head = L(ttl, "muted", ("ui", 8.5, "semi"))
        self.msg = L(self.text, "hi", ("ui", 10), wrap=True)
        lay.addWidget(self.head)
        lay.addWidget(self.msg)
        t = T()
        col = self._col()
        self.head.setStyleSheet(f"color:{col if t['dark'] else mix(col, '#000000', 0.25)};")
        self.adjustSize()
        self._life = QVariantAnimation(self)
        self._life.setStartValue(1.0)
        self._life.setEndValue(0.0)
        self._life.setDuration(int(life_ms))
        self._life.valueChanged.connect(self._set_frac)
        self._life.finished.connect(lambda: self.mgr.drop(self) if self.mgr is not None else self.deleteLater())
        sh = QGraphicsDropShadowEffect(self)
        sh.setBlurRadius(28)
        sh.setOffset(0, 6)
        sh.setColor(QColor(0, 0, 0, 110))
        self.setGraphicsEffect(sh)

    def _col(self):
        t = T()
        return {"bad": t["bad"], "warn": t["warn"], "ok": t["ok"]}.get(self.kind, t["accent"])

    def start(self):
        self._life.start()

    def _set_frac(self, v):
        self.frac = float(v)
        self.update()

    def enterEvent(self, e):
        if self._life.state() == QAbstractAnimation.State.Running:
            self._life.pause()
        super().enterEvent(e)

    def leaveEvent(self, e):
        if self._life.state() == QAbstractAnimation.State.Paused:
            self._life.resume()
        super().leaveEvent(e)

    def mousePressEvent(self, e):
        if self.mgr is not None:
            self.mgr.drop(self)

    def paintEvent(self, ev):
        t = T()
        col = self._col()
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing, True)
        r = QRectF(self.rect()).adjusted(0.5, 0.5, -0.5, -0.5)
        path = QPainterPath()
        path.addRoundedRect(r, 12, 12)
        p.fillPath(path, qc(t["raised"]))
        p.setPen(QPen(qc(mix(t["line"], col, 0.35)), 1.0))
        p.drawPath(path)
        p.save()
        p.setClipPath(path)
        p.fillRect(QRectF(0, 0, 4, self.height()), qc(col))
        p.fillRect(QRectF(0, self.height() - 2.5, self.width() * self.frac, 2.5), qc(mix(t["raised"], col, 0.8)))
        p.restore()
        p.end()


class ToastHost(QObject):
    def __init__(self, area, app):
        super().__init__(area)
        self.area = area
        self.app = app
        self.items = []
        self._anims = {}

    def show(self, text, kind="info", ms=None):
        if not self.app.config.get("ui_toasts", True):
            return
        now = time.time()
        for tw in self.items:
            if tw.text == text and now - tw.born < 6:
                return
        while len(self.items) >= 4:
            self.drop(self.items[0], fast=True)
        life = ms or (8000 if kind == "bad" else 4500)
        tw = Toast(self.area, text, kind, life, mgr=self)
        tw.adjustSize()
        self.items.append(tw)
        tw.show()
        tw.raise_()
        self._layout(new=tw)
        tw.start()

    def _target_x(self, tw):
        return self.area.width() - tw.width() - 22

    def _layout(self, new=None):
        y = 106
        for tw in reversed(self.items):
            tx = self._target_x(tw)
            if tw is new and MOTION.on:
                tw.move(self.area.width() + 10, y)
                self._slide(tw, QPoint(tx, y), 460, "back")
            else:
                if MOTION.on and tw.pos().y() != y:
                    self._slide(tw, QPoint(tx, y), 300, "out")
                elif not MOTION.on:
                    tw.move(tx, y)
            y += tw.height() + 10

    def _slide(self, tw, to, ms, ease):
        an = QPropertyAnimation(tw, b"pos", tw)
        an.setDuration(MOTION.ms(ms))
        an.setStartValue(tw.pos())
        an.setEndValue(to)
        c = QEasingCurve(_EASE.get(ease, QEasingCurve.Type.OutCubic))
        if ease == "back":
            c.setOvershoot(1.2)
        an.setEasingCurve(c)
        prev = self._anims.get(id(tw))
        if prev is not None:
            try:
                prev.stop()
            except RuntimeError:
                pass
        self._anims[id(tw)] = an
        an.start()

    def reflow(self):
        for tw in self.items:
            tw.move(self._target_x(tw), tw.pos().y())

    def drop(self, tw, fast=False):
        if tw not in self.items:
            return
        self.items.remove(tw)
        if MOTION.on and not fast:
            an = QPropertyAnimation(tw, b"pos", tw)
            an.setDuration(MOTION.ms(240))
            an.setStartValue(tw.pos())
            an.setEndValue(QPoint(self.area.width() + 20, tw.pos().y()))
            an.setEasingCurve(QEasingCurve(QEasingCurve.Type.InCubic))
            an.finished.connect(tw.deleteLater)
            self._anims[id(tw)] = an
            an.start()
        else:
            tw.deleteLater()
        self._layout()


def _fuzzy(q, text):
    q = q.lower().strip()
    s = text.lower()
    if not q:
        return 1.0
    if s.startswith(q):
        return 100.0 - len(s) * 0.01
    i = s.find(q)
    if i >= 0:
        return 80.0 - i - len(s) * 0.01
    words = s.replace("/", " ").split()
    if all(any(w.startswith(part) for w in words) for part in q.split()):
        return 60.0
    pos, score, last = 0, 0.0, -2
    for ch in q:
        k = s.find(ch, pos)
        if k < 0:
            return 0.0
        score += 3.0 if k == last + 1 else (2.0 if k == 0 or s[k - 1] in " -/" else 1.0)
        last = k
        pos = k + 1
    return 20.0 + score - len(s) * 0.02


class PaletteList(QWidget):
    activated = pyqtSignal(int)

    ROW = 44

    def __init__(self, parent=None):
        super().__init__(parent)
        self.items = []
        self.sel = 0
        self._hover = -1
        self._sel_y = 0.0
        self.setMouseTracking(True)
        self._anim = QVariantAnimation(self)
        self._anim.valueChanged.connect(self._set_sel_y)

    def set_items(self, items):
        self.items = items
        self.sel = 0
        self._sel_y = 0.0
        self.setFixedHeight(max(1, len(items)) * self.ROW + 8)
        self.update()

    def _set_sel_y(self, v):
        self._sel_y = float(v)
        self.update()

    def move_sel(self, d):
        if not self.items:
            return
        self.sel = (self.sel + d) % len(self.items)
        self._anim.stop()
        dur = MOTION.ms(160)
        if dur <= 0:
            self._set_sel_y(self.sel * self.ROW)
        else:
            self._anim.setStartValue(self._sel_y)
            self._anim.setEndValue(float(self.sel * self.ROW))
            self._anim.setDuration(dur)
            self._anim.setEasingCurve(QEasingCurve(QEasingCurve.Type.OutCubic))
            self._anim.start()

    def mouseMoveEvent(self, e):
        i = int((e.position().y() - 4) // self.ROW)
        if 0 <= i < len(self.items) and i != self.sel:
            self.sel = i
            self.move_sel(0)

    def mousePressEvent(self, e):
        i = int((e.position().y() - 4) // self.ROW)
        if 0 <= i < len(self.items):
            self.activated.emit(i)

    def paintEvent(self, ev):
        t = T()
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing, True)
        if not self.items:
            p.setFont(QF("ui", 10))
            p.setPen(qc(t["faint"]))
            p.drawText(QRectF(0, 0, self.width(), self.height()), int(Qt.AlignmentFlag.AlignCenter), "No matches")
            p.end()
            return
        sr = QRectF(6, 4 + self._sel_y, self.width() - 12, self.ROW - 2)
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(qc(mix(t["raised"], t["accent"], 0.16)))
        p.drawRoundedRect(sr, 9, 9)
        p.setBrush(qc(t["accent"]))
        p.drawRoundedRect(QRectF(6, sr.y() + 10, 3, sr.height() - 20), 1.5, 1.5)
        for i, it in enumerate(self.items):
            y = 4 + i * self.ROW
            active = i == self.sel
            ib = QRectF(20, y + (self.ROW - 28) / 2 - 1, 28, 28)
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(qc(mix(t["raised"], t["accent"], 0.22) if active else t["raised"]))
            p.drawRoundedRect(ib, 8, 8)
            draw_icon(p, it.get("icon", "sparkle"), ib.adjusted(6, 6, -6, -6),
                      qc(t["accent_text"] if active else t["muted"]), w=1.5)
            p.setFont(QF("ui", 10, "semi" if active else "normal"))
            p.setPen(qc(t["hi"] if active else t["text"]))
            p.drawText(QRectF(60, y, self.width() - 220, self.ROW - 2), int(Qt.AlignmentFlag.AlignVCenter), it["title"])
            p.setFont(QF("ui", 8.5))
            p.setPen(qc(t["muted"] if active else t["faint"]))
            p.drawText(QRectF(self.width() - 200, y, 180, self.ROW - 2),
                       int(Qt.AlignmentFlag.AlignVCenter | Qt.AlignmentFlag.AlignRight), it.get("hint", ""))
        p.end()


