def _user_logo(size):
    size = int(size)
    if size in _LOGO_CACHE:
        return _LOGO_CACHE[size]
    img = None
    for path in (os.path.join(_appdir(), "discord_logo.png"), os.path.abspath("discord_logo.png")):
        try:
            if os.path.isfile(path):
                pm = QPixmap(path)
                if not pm.isNull():
                    img = pm.scaled(size, size, Qt.AspectRatioMode.KeepAspectRatio, Qt.TransformationMode.SmoothTransformation)
                    break
        except Exception as _ex:
            _trace(_ex_where(), _ex)
    _LOGO_CACHE[size] = img
    return img

