    # ------------------------------------------------------------------ theme
    def _apply_palette(self):
        t = self._tok
        pal = QPalette()
        pal.setColor(QPalette.ColorRole.Window, qc(t["bg"]))
        pal.setColor(QPalette.ColorRole.WindowText, qc(t["text"]))
        pal.setColor(QPalette.ColorRole.Base, qc(t["input"]))
        pal.setColor(QPalette.ColorRole.AlternateBase, qc(t["card"]))
        pal.setColor(QPalette.ColorRole.Text, qc(t["hi"]))
        pal.setColor(QPalette.ColorRole.Button, qc(t["raised"]))
        pal.setColor(QPalette.ColorRole.ButtonText, qc(t["text"]))
        pal.setColor(QPalette.ColorRole.Highlight, qc(t["sel"]))
        pal.setColor(QPalette.ColorRole.HighlightedText, qc(t["hi"]))
        pal.setColor(QPalette.ColorRole.ToolTipBase, qc(t["raised"]))
        pal.setColor(QPalette.ColorRole.ToolTipText, qc(t["hi"]))
        pal.setColor(QPalette.ColorRole.PlaceholderText, qc(t["faint"]))
        pal.setColor(QPalette.ColorRole.Link, qc(t["info"]))
        try:
            self.qapp.setPalette(pal)
        except Exception as _ex:
            _trace(_ex_where(), _ex)

    def _studio_init(self):
        _qt_pick_fonts()
        self._ui_scale = 1.0
        _STUDIO["delta"] = int(self.config.get("ui_text_size", 0) or 0)
        self._scroll_canvases = set()
        self._repaint_hooks = []
        default_acc = "#8B5CF6" if self.is_multistream else None
        acc = self.config.get("accent_color") or default_acc
        name = self.config.get("ui_theme", "original")
        if name not in _STUDIO_BASE:
            name = "original"
        self.ui_theme = name
        tok = _studio_resolve(name, acc)
        _STUDIO["tok"] = tok
        _STUDIO["on"] = True
        self._tok = tok
        self.accent_main = tok["accent"]
        self.accent_hover = tok["accent_hover"]
        _STUDIO["accent_seen"].update({_hx(tok["accent"]), "#00e5ff", "#00b3cc"})
        self._theme_palette = tok
        self._apply_palette()
        self.qapp.setStyleSheet(build_qss(tok))
        plog("UI", f"qt ui: theme={name} accent={tok['accent']} text_size={_STUDIO['delta']:+d} qt={QT_VERSION_STR} pyqt={PYQT_VERSION_STR}")

    def _apply_tokens_everywhere(self):
        t0 = time.time()
        self._apply_palette()
        self.qapp.setStyleSheet(build_qss(self._tok))
        refont_all()
        for w in QApplication.allWidgets():
            if hasattr(w, "retheme"):
                try:
                    w.retheme()
                except Exception as _ex:
                    _trace(_ex_where(), _ex)
            w.update()
        try: theme_hub().changed.emit()
        except Exception as _ex:
            _trace(_ex_where(), _ex)
        try: self.tabview.apply_tokens()
        except Exception as _ex:
            _trace(_ex_where(), _ex)
        try: self.console_text.rerender()
        except Exception as _ex:
            _trace(_ex_where(), _ex)
        self._refresh_appearance_marks()
        self._run_repaint_hooks()
        _STUDIO["gen"] = _STUDIO.get("gen", 0) + 1
        try: _win_titlebar(self.win, self._tok["dark"])
        except Exception as _ex:
            _trace(_ex_where(), _ex)
        plog("UI", f"repainted in {(time.time()-t0)*1000:.0f}ms")

