    def _dip(self, fn):
        try:
            viewable = self.win.isVisible() and not self.win.isMinimized()
        except Exception:
            viewable = False
        if not MOTION.ambient or not viewable or getattr(self, "_dip_ov", None) is not None:
            try:
                fn()
            except Exception as _ex:
                log_crash("theme change", _ex)
            return
        host = self.win.centralWidget()
        try:
            pm = host.grab()
        except Exception:
            pm = None
        if pm is None or pm.isNull():
            fn()
            return
        ov = QLabel(host)
        ov.setPixmap(pm)
        ov.setGeometry(host.rect())
        ov.setAttribute(Qt.WidgetAttribute.WA_TransparentForMouseEvents, True)
        eff = QGraphicsOpacityEffect(ov)
        eff.setOpacity(1.0)
        ov.setGraphicsEffect(eff)
        ov.show()
        ov.raise_()
        self._dip_ov = ov
        try:
            fn()
        except Exception as _ex:
            log_crash("theme change", _ex)

        def step(v):
            try:
                eff.setOpacity(max(0.0, min(1.0, v)))
            except RuntimeError:
                pass

        def done():
            if self._dip_ov is ov:
                self._dip_ov = None
            try:
                ov.deleteLater()
            except RuntimeError:
                pass
        MOTION.tween("dip", 460, step, 0.0, a=1.0, ease="inout", done=done)
        QTimer.singleShot(3000, done)

    def _apply_motion_level(self):
        MOTION.set_level(self._motion_level_name())
        plog("UI", f"motion -> {MOTION.stats()}")
        if MOTION.ambient and getattr(self.tabview, "_current", None) is getattr(self, "tab_dash", None):
            self._dash_enter()
        self._refresh_appearance_marks()

    def _motion_start(self):
        MOTION.window = self.win
        MOTION.set_level(self._motion_level_name())
        plog("UI", f"motion engine attached - {MOTION.stats()}")

        def first_frame():
            if MOTION.ambient:
                try:
                    self.win.setWindowOpacity(0.0)
                    MOTION.tween("startup", 520, lambda v: self.win.setWindowOpacity(max(0.0, min(1.0, v))), 1.0, a=0.0,
                                 ease="out", done=lambda: self.win.setWindowOpacity(1.0))
                except Exception as _ex:
                    _trace(_ex_where(), _ex)
                try:
                    self.tabview.shine()
                except Exception as _ex:
                    _trace(_ex_where(), _ex)
            if getattr(self.tabview, "_current", None) is getattr(self, "tab_dash", None):
                self._dash_enter()

        def safety():
            try: self.win.setWindowOpacity(1.0)
            except Exception: pass
        QTimer.singleShot(60, first_frame)
        QTimer.singleShot(3000, safety)

    def _studio_keys(self):
        nav = getattr(self, "tabview", None)
        if nav is None:
            return
        self._shortcuts = []

        def sc(seq, fn):
            s = QShortcut(QKeySequence(seq), self.win)
            s.setContext(Qt.ShortcutContext.ApplicationShortcut)
            s.activated.connect(fn)
            self._shortcuts.append(s)

        def _focus_cmd():
            try:
                nav.palette.close()
                nav.select(self.tab_dash)
                QTimer.singleShot(40, self.entry_cmd.setFocus)
            except Exception as _ex:
                _trace(_ex_where(), _ex)
        sc("Ctrl+K", nav.focus_search)
        sc("Ctrl+P", nav.focus_search)
        sc("Ctrl+J", nav.toggle_chat_pane)
        sc("Ctrl+Tab", lambda: nav.step(1))
        sc("Ctrl+Shift+Tab", lambda: nav.step(-1))
        sc("Ctrl+L", _focus_cmd)

    def _studio_finish(self):
        self._studio_ready = True
        self._refresh_appearance_marks()
        try: self.tabview.apply_tokens()
        except Exception as _ex:
            _trace(_ex_where(), _ex)
        try: self.tabview.select(self.tabview._current)
        except Exception as _ex:
            _trace(_ex_where(), _ex)
        self._run_repaint_hooks()
        self._motion_start()
        self._studio_keys()
        QTimer.singleShot(150, lambda: _win_titlebar(self.win, self._tok["dark"]))

    def _on_page_shown(self, page):
        if page is getattr(self, "tab_dash", None):
            self._dash_enter()
        else:
            MOTION.unloop("sparkpulse", rest=False)
            for _c in getattr(self, "_metric", {}).values():
                try:
                    if isinstance(_c["cv"], Spark):
                        _c["cv"]._set_pulse(0.0)
                except Exception:
                    pass
        if page is getattr(self, "tab_discord", None):
            MOTION.loop("dcmark", self._discord_mark_frame, 2600, fps=24)
        else:
            MOTION.unloop("dcmark", rest=False)

