    def _refresh_appearance_marks(self):
        try:
            for key, sw in getattr(self, "_theme_cards", {}).items():
                sw.set_selected(key == self.ui_theme)
            cur = self.config.get("accent_color")
            for col, chip in getattr(self, "_accent_chips", {}).items():
                chip.set_selected((col or None) == (cur or None))
            seg = getattr(self, "_size_seg", None)
            if seg is not None:
                seg.set(int(_STUDIO.get("delta", 0)))
            ms = getattr(self, "_motion_seg", None)
            if ms is not None:
                ms.set(str(self.config.get("ui_motion", "full")).lower())
        except Exception as _ex:
            _trace(_ex_where(), _ex)

