    def _refresh_snippets(self):
        lay = self.snip_wrap.layout()
        _clear_layout(lay)
        snips = self.config.get("snippets", [])
        if not snips:
            lay.addWidget(L("No snippets yet.", "faint", ("ui", 9.5)))
        for i, sn in enumerate(snips):
            row = QWidget()
            rl = QHBoxLayout(row)
            rl.setContentsMargins(0, 0, 0, 0)
            rl.setSpacing(10)
            rl.addWidget(Button("Type", lambda t=sn: self._send_cmd("!type", t), "primary", "sm", icon="text"))
            lab = L(sn[:80] + ("..." if len(sn) > 80 else ""), "text", ("mono", 10))
            lab.setSizePolicy(QSizePolicy.Policy.Ignored, QSizePolicy.Policy.Preferred)
            rl.addWidget(lab, 1)
            rl.addWidget(IconButton("trash", lambda idx=i: self._snip_del(idx), "Delete", 30))
            lay.addWidget(row)

