    # ------------------------------------------------------------------ changevm and command power
    def build_changevm_tab(self):
        sc = self.make_scrollable(self.tab_changevm)
        c = Card("Whitelisted VMs and snapshots",
                 "!changevm switches the active VM and reverts its snapshot. Pick which VMs viewers can switch to, and which "
                 "snapshot each one reverts to. An empty whitelist means only the current VM is allowed.")
        self.var_changevm_enabled = Toggle("Enable !changevm", bool(getattr(self, "changevm_enabled", True)),
                                           command=self._apply_changevm_enabled)
        c.add_action(self.var_changevm_enabled)
        c.add_action(Button("Refresh VM list", self._cv_refresh, "neutral", "sm", icon="refresh"))
        self.cv_rows = QWidget()
        rl = QVBoxLayout(self.cv_rows)
        rl.setContentsMargins(0, 0, 0, 0)
        rl.setSpacing(6)
        c.add(self.cv_rows)
        self.cv_card = c
        self.cv_vars = {}
        self.cv_snap_vars = {}
        self.cv_snap_boxes = {}
        self.cv_available = []
        self.cv_hint = L("", "faint", ("ui", 9))
        c.add(row_widget(Button("Save ChangeVM list", self._cv_save, "primary", "md", icon="check"), 10, self.cv_hint, "stretch"))
        sc.add(c)
        sc.add("stretch")
        self._cv_refresh()

    def _cv_refresh(self):
        lay = self.cv_rows.layout()
        _clear_layout(lay)
        self.cv_vars = {}
        self.cv_snap_vars = {}
        self.cv_snap_boxes = {}
        try:
            vms = self._cv_available_vms()
        except Exception:
            vms = []
        self.cv_available = vms
        cur = vm_name
        whitelist = set(self.changevm_whitelist)
        for name in vms:
            row = Card(pad=10, tint="accent" if name == cur else None)
            hl = QHBoxLayout()
            hl.setSpacing(10)
            tg = Toggle(name, (name in whitelist) or (not whitelist and name == cur))
            tg._qf = ("mono", 10, "semi")
            tg.setFont(QF(*tg._qf))
            hl.addWidget(tg, 1)
            if name == cur:
                hl.addWidget(Pill("CURRENT", "accent"))
            hl.addWidget(L("snapshot", "faint", ("ui", 9)))
            cb = Combo([self.changevm_snapshots.get(name, "")] if self.changevm_snapshots.get(name) else [""],
                       self.changevm_snapshots.get(name, ""), width=240)
            hl.addWidget(cb)
            row.body.addLayout(hl)
            lay.addWidget(row)
            self.cv_vars[name] = tg
            self.cv_snap_vars[name] = cb
            self.cv_snap_boxes[name] = cb
        if not vms:
            lay.addWidget(EmptyState("vms", "No VMs found", "Add one in VirtualBox (or pick a .vmx on the VMS page) and press Refresh."))
        self.cv_hint.setText(f"{len(vms)} VM(s) found   /   whitelisted: {len(whitelist) if whitelist else 'current VM only'}")
        path = self.config.get("vbox_path", vbox_manage_cmd) or vbox_manage_cmd
        names = list(vms)

        def work():
            res = {}
            for n in names:
                try:
                    res[n] = get_vbox_snapshots(path, n)
                except Exception:
                    res[n] = []
            self.ui(self._cv_apply_snaps, res)
        if names and getattr(self, "backend", "virtualbox") != "vmware":
            self._run_bg("cv-snaps", work)

    def _cv_apply_snaps(self, res):
        for n, snaps in res.items():
            cb = self.cv_snap_boxes.get(n)
            if cb is None:
                continue
            try:
                want = self.changevm_snapshots.get(n, "") or cb.get()
                cb.set_values(snaps or [""])
                if want in snaps:
                    cb.set(want)
                elif snaps:
                    cb.set(snaps[-1])
            except RuntimeError:
                pass

    def _cv_save(self):
        wl = [n for n, v in self.cv_vars.items() if v.get()]
        snaps = {}
        for n, sv in self.cv_snap_vars.items():
            v = sv.get().strip()
            if v:
                snaps[n] = v
        self.changevm_whitelist = wl
        self.changevm_snapshots = snaps
        self.config["changevm_whitelist"] = wl
        self.config["changevm_snapshots"] = snaps
        self.save_settings()
        self.cv_hint.setText(f"saved: {len(wl)} whitelisted VM(s)")
        self.log("[system]", f"changevm whitelist: {wl if wl else 'current VM only'}", "sysmsg")
        self.toast("ChangeVM list saved", "ok")

    def build_command_power_tab(self):
        sc = self.make_scrollable(self.tab_cmdpower)
        c = Card("Who can run VM commands",
                 "Set every advanced command to Everyone, Admins only or Disabled, plus an optional per-user countdown. "
                 "A countdown blocks the same viewer from running that command again until it runs out (0 = off). The owner always gets through.")
        cmds = ["!revert", "!startvm", "!shutdown", "!restartvm", "!switchsnapshot", "!makesnapshot",
                "!changevm", "!remake2", "!fixvm", "!forcefixvm", "!snapshotnow", "!revertnow", "!restartnow"]
        self.cp_rows = {}
        self.cp_entries = {}
        grid = QGridLayout()
        grid.setHorizontalSpacing(18)
        grid.setVerticalSpacing(8)
        for col, txt in enumerate(("Command", "Access", "Countdown (s)")):
            grid.addWidget(L(txt, "muted", ("ui", 9, "semi")), 0, col)
        for i, cm in enumerate(cmds, start=1):
            grid.addWidget(L(cm, "hi", ("mono", 10.5)), i, 0)
            lvl = str(self.command_power.get(cm, {}).get("level", "everyone"))
            if lvl.startswith("admin"):
                lvl = "admins only"
            elif lvl not in ("everyone", "disabled"):
                lvl = "everyone"
            seg = Segmented((("everyone", "Everyone"), ("admins only", "Admins only"), ("disabled", "Disabled")), lvl)
            self.cp_rows[cm] = seg
            grid.addWidget(seg, i, 1, Qt.AlignmentFlag.AlignLeft)
            ent = NumberEdit(int(self.command_power.get(cm, {}).get("countdown", 0) or 0), 100)
            self.cp_entries[cm] = ent
            grid.addWidget(ent, i, 2, Qt.AlignmentFlag.AlignLeft)
        grid.setColumnStretch(3, 1)
        c.add(grid)
        self.cp_hint = L("", "faint", ("ui", 9))
        c.add(row_widget(Button("Save command power", self._cp_save, "primary", "md", icon="check"), 10, self.cp_hint, "stretch"))
        sc.add(c)
        sc.add("stretch")

    def _cp_save(self):
        power = {}
        for cm, seg in self.cp_rows.items():
            lvl = seg.get()
            try:
                cd = float(self.cp_entries[cm].get().strip() or 0)
            except Exception:
                cd = 0.0
            cd = max(0.0, min(cd, 3600.0))
            power[cm] = {"level": lvl, "countdown": cd}
        self.command_power = power
        self.config["command_power"] = power
        self.save_settings()
        self.cp_hint.setText(f"saved: {len(power)} command(s)")
        self.log("[system]", f"command power updated: {len(power)} command(s)", "sysmsg")
        self.toast("Command power saved", "ok")

