    def _paint_discord_mode(self, animate=True):
        cur = self._discord_mode_var.get() if hasattr(self, "_discord_mode_var") else "crossplay"
        for v, r in getattr(self, "_discord_mode_rows", {}).items():
            r.set_selected(v == cur, animate=animate)

    def _set_discord_hint(self, text, kind="muted"):
        if not hasattr(self, "_discord_hint"):
            return
        if threading.current_thread() is not threading.main_thread():
            self.ui(self._set_discord_hint, text, kind)
            return
        self._discord_hint.setText(text)
        set_role(self._discord_hint, {"ok": "ok", "bad": "bad", "warn": "warn"}.get(kind, "muted"))

    def _sync_security_marks(self):
        on = self._b64_filter_on()
        if hasattr(self, "_b64_var"):
            try: self._b64_var.set(on)
            except Exception: pass
        if hasattr(self, "_b64_pill"):
            try: self._b64_pill.set("ON" if on else "OFF", "ok" if on else "bad")
            except Exception as _ex:
                _trace(_ex_where(), _ex)
        if hasattr(self, "_b64_block_lbl"):
            n = len(getattr(self, "b64_offenders", ()))
            try:
                self._b64_block_lbl.setText(f"{n} sender{'s' if n != 1 else ''} currently blocked." if n else "No senders blocked.")
                set_role(self._b64_block_lbl, "warn" if n else "muted")
            except Exception as _ex:
                _trace(_ex_where(), _ex)

    def _refresh_discord_page(self):
        if not getattr(self, "_discord_built", False):
            return
        if threading.current_thread() is not threading.main_thread():
            self.ui(self._refresh_discord_page)
            return
        br = getattr(self, "discord", None)
        self._discord_logo()
        running = bool(br and br.running)
        if hasattr(self, "btn_crossplay"):
            mode = self._discord_mode_var.get() if hasattr(self, "_discord_mode_var") else "crossplay"
            if running:
                self.btn_crossplay.setText("Stop the Discord bot")
                self.btn_crossplay.setVariant("danger")
                self.btn_crossplay.setIcon("power")
            else:
                self.btn_crossplay.setText("Enable Discord & YouTube crossplay" if mode == "crossplay" else "Enable Discord bot")
                self.btn_crossplay.setVariant("primary")
                self.btn_crossplay.setIcon("bridge")
            self.btn_crossplay.updateGeometry()
        self._sync_security_marks()
        self._paint_discord_mode()
        state = (br.state if br else "stopped")
        detail = (br.detail if br else "")
        colors = {"online": "ok", "connecting": "warn", "installing": "warn", "error": "bad", "stopped": "muted"}
        if hasattr(self, "_discord_state_lbl"):
            txt = {"online": "Online", "connecting": "Connecting", "installing": "Installing discord.py",
                   "error": "Problem", "stopped": "Stopped"}.get(state, state.title())
            if br and br.online:
                ch = br.channel_name(self._did("discord_channel_id"))
                txt = f"Online as {br.user_tag}" + (f"  -  commands from {ch}" if ch else "  -  pick a command channel below")
            elif detail:
                txt = f"{txt} - {detail}"
            self._discord_state_lbl.setText(txt)
            set_role(self._discord_state_lbl, colors.get(state, "muted"))

    def _discord_poll(self):
        if not getattr(self, "running", True):
            return
        br = getattr(self, "discord", None)
        try:
            if br is not None and getattr(self, "_discord_built", False):
                if br.guilds_dirty:
                    self._fill_discord_combos()
                if br.dirty:
                    br.dirty = False
                    self._refresh_discord_page()
                    if hasattr(self, "_discord_stat_lbls"):
                        st = br.stats
                        lb = self._discord_stat_lbls["bot"]
                        lb.setText({"online": "online", "connecting": "...", "installing": "setup", "error": "error", "stopped": "off"}.get(br.state, br.state))
                        set_role(lb, {"online": "ok", "error": "bad"}.get(br.state, "muted"))
                        for key in ("in", "cmds", "shots", "blocked", "errors"):
                            self._discord_stat_lbls[key].setText(str(st.get(key, 0)))
                    ev = list(br.events)[-40:]
                    cur = getattr(self, "_discord_ev_n", -1)
                    sig = (len(br.events), ev[-1] if ev else None)
                    if sig != cur:
                        self._discord_ev_n = sig
                        self.discord_events.set_text("\n".join(f"{ts}  {line}" for ts, line in ev))
                        sb = self.discord_events.verticalScrollBar()
                        sb.setValue(sb.maximum())
        except Exception as _ex:
            _trace(_ex_where(), _ex)
        try:
            self.root.after(700, self._discord_poll)
        except Exception as _ex:
            _trace(_ex_where(), _ex)

    # ------------------------------------------------------------------ plugins
    def build_plugins_tab(self):
        sc = self.make_scrollable(self.tab_plugins)
        bar = row_widget(L("Plugins add chat commands, timers and panels. They live in the plugins folder next to yt2vm.py "
                           "and run with the same access as the app, so only install ones you trust.", "muted", ("ui", 9.5), wrap=True), 1)
        sc.add(bar)
        sc.add(row_widget(Button("Plugin market", lambda: self.tabview.select(self.tab_market), "primary", "sm", icon="bag"),
                          Button("New plugin", self._plugin_new, "neutral", "sm", icon="plus"),
                          Button("Docs", self.plugin_docs_open, "neutral", "sm", icon="book"),
                          Button("Open folder", lambda: self._open_file(plugins_dir()), "neutral", "sm", icon="folder"),
                          Button("Reload all", lambda: self._run_bg("plugins-reload", self.plugins.reload_all), "neutral", "sm", icon="refresh"),
                          "stretch"))
        self._plugins_list = QWidget()
        pl = QVBoxLayout(self._plugins_list)
        pl.setContentsMargins(0, 0, 0, 0)
        pl.setSpacing(12)
        sc.add(self._plugins_list)
        sc.add("stretch")
        self.plugins.add_listener(self._render_plugins)
        self._render_plugins()

    def _render_plugins(self):
        host = getattr(self, "_plugins_list", None)
        if host is None:
            return
        lay = host.layout()
        _clear_layout(lay)
        pm = self.plugins
        items = sorted(pm.plugins.values(), key=lambda p: p.name.lower())
        if not items:
            c = Card(pad=22)
            c.add(EmptyState("puzzle", "No plugins installed yet",
                             "Grab one from the Plugin market, or drop a folder with plugin.json + plugin.py into the plugins folder "
                             "and press Reload all. The Plugin Docs page shows how to write your own."))
            lay.addWidget(c)
        for i, p in enumerate(items):
            try:
                card = self._plugin_card(host, p)
                if card is not None:
                    lay.addWidget(card)
                    if MOTION.on and getattr(self.tabview, "_current", None) is self.tab_plugins:
                        self._rise(card, delay=i * 40, dur=380)
            except Exception as e:
                log_crash(f"plugin card {getattr(p, 'id', '?')}", e)

    def _plugin_card(self, host, p):
        m = p.manifest
        on = self.plugins.is_enabled(p.id)
        if p.error: state, col = "Error", "bad"
        elif p.loaded: state, col = "Running", "ok"
        elif on: state, col = "Not loaded - click Reload", "warn"
        else: state, col = "Disabled", "faint"
        c = Card(pad=18, tint="bad" if p.error else None)
        top = QHBoxLayout()
        top.setSpacing(8)
        top.addWidget(L(p.name, "hi", ("ui", 12, "semi")))
        top.addWidget(L(f"v{m.get('version')}  by {m.get('author')}", "faint", ("ui", 9)), 0, Qt.AlignmentFlag.AlignBottom)
        top.addStretch(1)
        dot = Dot(col if col != "faint" else "faint", 8, pulse=(col == "ok"))
        top.addWidget(dot)
        top.addWidget(L(state, col if col != "faint" else "muted", ("ui", 9, "semi")))
        c.body.addLayout(top)
        if m.get("description"):
            c.add(L(m["description"], "muted", ("ui", 9.5), wrap=True))
        if p.error:
            c.add(L(p.error, "bad", ("mono", 9), wrap=True, sel=True))
        if p.commands:
            pre = self.command_prefix or "!"
            cmds = "   ".join(f"{pre}{n}" + (" (mods)" if s["mod_only"] else "") for n, s in sorted(p.commands.items()))
            c.add(L("Commands:  " + cmds, "text", ("mono", 9), wrap=True, sel=True))
        row = QHBoxLayout()
        row.setSpacing(8)
        row.addWidget(Button("Disable" if on else "Enable", lambda: self._run_bg(f"plugin-{p.id}", self.plugins.set_enabled, p.id, not on),
                             "neutral" if on else "go", "sm", icon="power"))
        row.addWidget(Button("Reload", lambda: self._run_bg(f"plugin-{p.id}", self.plugins.reload, p.id), "neutral", "sm", icon="refresh"))
        row.addWidget(Button("Open folder", lambda: self._open_file(p.folder), "neutral", "sm", icon="folder"))
        if self._plugin_submittable(p)[0]:
            row.addWidget(Button("Submit", lambda: self._plugin_submit(p.id), "neutral", "sm", icon="send"))
        row.addStretch(1)
        row.addWidget(Button("Uninstall", lambda: self._plugin_uninstall(p.id), "danger", "sm", icon="trash"))
        c.body.addLayout(row)
        for title, build in list(p.panels):
            c.add(Divider())
            if title and title != p.name:
                c.add(L(title, "muted", ("ui", 9, "semi")))
            box = QWidget()
            c.add(box)
            self._plugin_build(p, build, box, "panel")
        return c

    def _plugin_build(self, p, build, box, what):
        ui = PluginUI(box, p)
        try:
            build(ui)
        except Exception as e:
            ui.clear()
            msg = str(e)
            tkish = isinstance(e, (AttributeError, TypeError, ImportError)) or "tk" in msg.lower()
            if tkish:
                plog("PLUGIN", f"{p.id}: {what} looks like it was written for the old Tkinter UI ({type(e).__name__}: {e})")
                note = Card(pad=12, tint="warn")
                note.add(L(f"This {what} was made for the old Tkinter window and needs an update for plugin API {PLUGIN_API_VERSION} (PyQt6). "
                           "Its commands and timers still work.", "warn_soft", ("ui", 9.5), wrap=True))
                ui.add(note)
            else:
                log_crash(f"plugin {p.id} {what}", e)
                ui.add(L(f"{what} failed: {e}", "bad", ("mono", 9), wrap=True))

    def build_market_tab(self):
        sc = self.make_scrollable(self.tab_market)
        self._market_items = []
        self._market_busy = False
        server = market_server_url()
        if server:
            sc.add(L(f"Every plugin here was reviewed before it was published.  Market: {server}", "muted", ("ui", 9.5), wrap=True))
        else:
            c = Card("The plugin market isn't available in this build yet.",
                     "You can still install plugins by copying their folder into the plugins folder and pressing Reload all on the Plugins page.")
            sc.add(c)
        self.market_filter = LineEdit("", "Search plugins...")
        self.market_filter.textChanged.connect(lambda *_: self._render_market())
        self.market_status = L("Press Refresh to load the market.", "faint", ("ui", 9))
        self._market_spin = Spinner(16)
        self._market_spin.hide()
        sc.add(row_widget(self.market_filter, self._market_spin, self.market_status,
                          Button("Docs", lambda: self.plugin_docs_open("plugin-market"), "neutral", "sm", icon="book"),
                          Button("Refresh", self._market_refresh, "primary", "sm", icon="refresh")))
        self._market_list = QWidget()
        ml = QVBoxLayout(self._market_list)
        ml.setContentsMargins(0, 0, 0, 0)
        ml.setSpacing(12)
        sc.add(self._market_list)
        sc.add("stretch")
        self.plugins.add_listener(self._market_changed)
        if self.config.get("plugin_market_autoload", True):
            self.root.after(1500, self._market_refresh)

    def _market_set_status(self, text, fg="faint"):
        lbl = getattr(self, "market_status", None)
        if lbl is None:
            return

        def go():
            lbl.setText(text)
            set_role(lbl, fg if fg in _ROLE_KEYS else "faint")
            sp = getattr(self, "_market_spin", None)
            if sp is not None:
                if text.endswith("...") and fg == "faint":
                    sp.start()
                else:
                    sp.stop()
        self.ui(go)

    def _render_market(self):
        host = getattr(self, "_market_list", None)
        if host is None:
            return
        lay = host.layout()
        _clear_layout(lay)
        flt = ""
        try: flt = self.market_filter.get().strip().lower()
        except Exception as _ex:
            _trace(_ex_where(), _ex)
        shown = 0
        for e in self._market_items:
            blob = " ".join(str(e.get(k, "")) for k in ("id", "name", "author", "description")) + " " + " ".join(e.get("tags") or [])
            if flt and flt not in blob.lower():
                continue
            try:
                card = self._market_card(host, e)
                lay.addWidget(card)
                if MOTION.on and getattr(self.tabview, "_current", None) is self.tab_market and not flt:
                    self._rise(card, delay=shown * 40, dur=380)
            except Exception as ex:
                log_crash(f"market card {e.get('id')}", ex)
            shown += 1
        if not shown and self._market_items:
            lay.addWidget(EmptyState("search", "Nothing matches that search", "Try a different word."))

    def _market_card(self, host, e):
        inst = self.plugins.plugins.get(e["id"])
        c = Card(pad=18)
        top = QHBoxLayout()
        top.setSpacing(8)
        top.addWidget(L(e.get("name") or e["id"], "hi", ("ui", 12, "semi")))
        top.addWidget(L(f"v{e.get('version', '?')}  by {e.get('author', 'unknown')}", "faint", ("ui", 9)), 0, Qt.AlignmentFlag.AlignBottom)
        top.addStretch(1)
        if inst is not None:
            have = inst.manifest.get("version", "0")
            newer = _version_tuple(e.get("version")) > _version_tuple(have)
            top.addWidget(Pill("UPDATE" if newer else "INSTALLED", "warn" if newer else "ok"))
        c.body.addLayout(top)
        if e.get("description"):
            c.add(L(e["description"], "muted", ("ui", 9.5), wrap=True))
        meta = []
        if e.get("tags"): meta.append("  ".join("#" + str(x) for x in e["tags"]))
        if e.get("commands"): meta.append("adds " + " ".join("!" + str(x).lstrip("!") for x in e["commands"]))
        if meta:
            c.add(L("   /   ".join(meta), "faint", ("ui", 8.5), wrap=True))
        row = QHBoxLayout()
        row.setSpacing(8)
        if inst is None:
            row.addWidget(Button("Install", lambda: self._market_install(e), "primary", "sm", icon="download"))
        else:
            have = inst.manifest.get("version", "0")
            if _version_tuple(e.get("version")) > _version_tuple(have):
                row.addWidget(Button(f"Update {have} -> {e.get('version')}", lambda: self._market_install(e), "primary", "sm", icon="download"))
            else:
                row.addWidget(Button("Reinstall", lambda: self._market_install(e), "neutral", "sm", icon="refresh"))
        if e.get("homepage"):
            row.addWidget(Button("Homepage", lambda: self._market_open_home(e["homepage"]), "neutral", "sm", icon="globe"))
        row.addStretch(1)
        if inst is not None:
            row.addWidget(Button("Uninstall", lambda: self._plugin_uninstall(e["id"]), "danger", "sm", icon="trash"))
        c.body.addLayout(row)
        return c

    def _plugin_new(self):
        pid = simpledialog.askstring("New plugin", "Plugin id (lowercase letters, digits, - and _):")
        if not pid:
            return
        try:
            folder, cmd = plugin_scaffold(pid)
        except Exception as e:
            messagebox.showerror("New plugin", str(e))
            return

        def work():
            self.plugins.discover()
            ok = self.plugins.load(pid.strip().lower())
            pre = self.command_prefix or "!"
            self.toast(f"Created plugins/{os.path.basename(folder)} - try {pre}{cmd}" if ok else "Plugin created but failed to load",
                       "ok" if ok else "bad")
            self.ui(self._open_file, folder)
        self._run_bg("plugin-new", work)

    def _plugin_submit(self, pid):
        p = self.plugins.plugins.get(pid)
        if p is None:
            return
        ok, why = self._plugin_submittable(p)
        if not ok:
            messagebox.showinfo("Submit plugin", why)
            return
        server = market_server_url()
        if not server:
            messagebox.showinfo("Submit plugin", "This build of YT2VM has no plugin market yet, so there is nowhere to submit to.")
            return
        keys = self.config.setdefault("plugin_owner_keys", {}).setdefault(server, {})
        note = simpledialog.askstring(
            "Submit plugin",
            f"Upload {p.name} {p.manifest.get('version')} to\n{server}\n\n"
            + ("This is an update to your plugin." if keys.get(pid) else "This id is new on the market - it will be reserved for you.")
            + "\n\nNote for the reviewer (optional):")
        if note is None:
            return

        def work():
            try:
                res = market_submit(server, p.folder, keys.get(pid, ""), note)
            except ValueError as e:
                errs = e.args[0] if e.args and isinstance(e.args[0], list) else [str(e)]
                self.ui(messagebox.showerror, "Submit plugin", "The server refused the upload:\n\n- " + "\n- ".join(map(str, errs)))
                return
            except Exception as e:
                log_crash(f"submit {pid}", e)
                self.ui(messagebox.showerror, "Submit plugin", f"Upload failed: {e}")
                return
            msg = f"{p.name} {res.get('version')} was uploaded."
            msg += ("\n\nIt is waiting for review - it shows up in the market once an admin approves it."
                    if res.get("status") == "pending" else "\n\nIt is published now.")
            if res.get("owner_key"):
                keys[pid] = res["owner_key"]
                self.save_settings()
                msg += ("\n\nYour owner key for this plugin is saved in settings.json. You need it to publish updates, "
                        "so back it up:\n\n" + res["owner_key"])
            plog("MARKET", f"submitted {pid} {res.get('version')} to {server}: {res.get('status')}")
            self.toast(f"Submitted {p.name} {res.get('version')}", "ok")
            self.ui(messagebox.showinfo, "Submit plugin", msg)
        self._run_bg(f"plugin-submit-{pid}", work)

    # ------------------------------------------------------------------ plugin docs
    def plugin_docs_open(self, doc_key=None, anchor=None):
        self.tabview.select(self.tab_plugindocs)
        if doc_key:
            self.root.after(60, lambda: self._docs_jump(f"{doc_key}#{anchor}" if anchor else f"{doc_key}#"))

    def build_plugindocs_tab(self):
        page = self.tab_plugindocs
        lay = page.layout()
        lay.setContentsMargins(28, 22, 28, 24)
        lay.setSpacing(12)
        self.docs_find = LineEdit("", "Find in the docs (Enter)", on_enter=self._docs_search, width=280)
        lay.addWidget(row_widget(Button("New plugin", self._plugin_new, "primary", "sm", icon="plus"),
                                 Button("Plugins", lambda: self.tabview.select(self.tab_plugins), "neutral", "sm", icon="puzzle"),
                                 Button("Plugin market", lambda: self.tabview.select(self.tab_market), "neutral", "sm", icon="bag"),
                                 "stretch", self.docs_find))
        body = QHBoxLayout()
        body.setSpacing(14)
        self.docs_nav = ListBox(size=9.5, on_select=self._docs_nav_pick)
        self.docs_nav.setFixedWidth(260)
        body.addWidget(self.docs_nav)
        card = Card(pad=0)
        self.docs_text = QTextBrowser()
        self.docs_text.setProperty("flat", True)
        self.docs_text.setFrameShape(QFrame.Shape.NoFrame)
        self.docs_text.setOpenLinks(False)
        self.docs_text.setOpenExternalLinks(False)
        self.docs_text.anchorClicked.connect(lambda url: self._docs_follow(url.toString()))
        self.docs_text.setViewportMargins(18, 12, 10, 12)
        card.body.addWidget(self.docs_text, 1)
        body.addWidget(card, 1)
        lay.addLayout(body, 1)
        self._docs_nav_marks = []
        self._docs_anchor_pos = {}
        self._docs_render()
        self._repaint_hooks.append(self._docs_paint)

    def _docs_paint(self):
        if getattr(self, "docs_text", None) is not None:
            sb = self.docs_text.verticalScrollBar()
            v = sb.value()
            self._docs_render(keep_nav=True)
            QTimer.singleShot(0, lambda: sb.setValue(v))

    def _docs_esc(self, s):
        return html.escape(str(s), quote=False)

    def _docs_inline(self, text, tags=()):
        pat = re.compile(r"(`[^`]+`)|(\*\*[^*]+\*\*)|(\[[^\]]+\]\([^)\s]+\))|(<https?://[^>\s]+>)")
        out = []
        pos = 0
        t = self._tok
        for m in pat.finditer(text):
            if m.start() > pos:
                out.append(self._docs_esc(text[pos:m.start()]))
            tok = m.group(0)
            if m.group(1):
                out.append(f'<code style="background-color:{t["input"]};color:{t["accent_text"]};">&nbsp;{self._docs_esc(tok[1:-1])}&nbsp;</code>')
            elif m.group(2):
                out.append(f'<b style="color:{t["hi"]};">{self._docs_esc(tok[2:-2])}</b>')
            else:
                if m.group(3):
                    label, target = re.match(r"\[([^\]]+)\]\(([^)\s]+)\)", tok).groups()
                else:
                    label = target = tok[1:-1]
                out.append(f'<a href="{html.escape(target, quote=True)}" style="color:{t["info"]};">{self._docs_esc(label)}</a>')
            pos = m.end()
        if pos < len(text):
            out.append(self._docs_esc(text[pos:]))
        return "".join(out)

    def _docs_anchor(self, key, slug=""):
        return f"{key}--{slug}"

    def _docs_render(self, keep_nav=False):
        tx = self.docs_text
        t = self._tok
        mono = _QF.get("mono") or "monospace"
        disp = _QF.get("display") or _QF.get("ui") or "sans-serif"
        css = (f"body{{color:{t['text']};font-family:'{_QF.get('ui')}';}}"
               f"h1{{color:{t['hi']};font-family:'{disp}';font-size:21pt;font-weight:600;margin-top:4px;margin-bottom:10px;}}"
               f"h2{{color:{t['hi']};font-family:'{disp}';font-size:15pt;font-weight:600;margin-top:22px;margin-bottom:6px;}}"
               f"h3{{color:{t['hi']};font-size:11pt;font-weight:700;margin-top:14px;margin-bottom:4px;}}"
               f"p{{margin-top:3px;margin-bottom:7px;line-height:140%;}}"
               f"pre{{background-color:{t['input']};color:{t['text']};font-family:'{mono}';font-size:9pt;padding:10px;margin-top:4px;margin-bottom:10px;}}"
               f"code{{font-family:'{mono}';font-size:9pt;}}"
               f"td{{padding:5px 10px 5px 0;vertical-align:top;}}"
               f"th{{color:{t['muted']};text-align:left;padding:5px 10px 5px 0;font-weight:600;border-bottom:1px solid {t['line']};}}"
               f"blockquote{{color:{t['muted']};margin-left:14px;}}"
               f"li{{margin-bottom:3px;}}"
               f"hr{{color:{t['line']};}}")
        tx.document().setDefaultStyleSheet(css)
        nav_items = []
        self._docs_nav_marks = []
        parts = []
        for key, title, md in PLUGIN_DOCS:
            anc = self._docs_anchor(key)
            parts.append(f'<a name="{anc}"></a>')
            nav_items.append(title)
            self._docs_nav_marks.append(anc)
            lines = md.strip("\n").splitlines()
            i, in_code, code_buf = 0, False, []
            in_list = None
            while i < len(lines):
                line = lines[i]
                if line.startswith("```"):
                    if in_list:
                        parts.append(f"</{in_list}>"); in_list = None
                    if in_code:
                        parts.append("<pre>" + self._docs_esc("\n".join(code_buf)) + "</pre>")
                        code_buf = []
                    in_code = not in_code
                    i += 1; continue
                if in_code:
                    code_buf.append(line); i += 1; continue
                h = re.match(r"(#{1,3}) (.*)", line)
                if h:
                    if in_list:
                        parts.append(f"</{in_list}>"); in_list = None
                    lvl, text = len(h.group(1)), h.group(2).strip()
                    anc = self._docs_anchor(key, self._docs_slug(text))
                    parts.append(f'<a name="{anc}"></a><h{lvl}>{self._docs_inline(text)}</h{lvl}>')
                    if lvl == 2:
                        nav_items.append("      " + re.sub(r"[`*]", "", text))
                        self._docs_nav_marks.append(anc)
                    i += 1; continue
                if line.startswith("|"):
                    if in_list:
                        parts.append(f"</{in_list}>"); in_list = None
                    rows = []
                    while i < len(lines) and lines[i].startswith("|"):
                        cells = [c.strip() for c in lines[i].strip().strip("|").split("|")]
                        if not all(re.fullmatch(r":?-{2,}:?", c) for c in cells):
                            rows.append(cells)
                        i += 1
                    head, rest = rows[0], rows[1:]
                    tb = ['<table cellspacing="0" cellpadding="5" width="100%">', "<tr>"]
                    tb += [f"<th>{self._docs_inline(c)}</th>" for c in head]
                    tb.append("</tr>")
                    for r in rest:
                        tb.append("<tr>")
                        for j, cval in enumerate(r):
                            if j == 0:
                                tb.append(f'<td style="color:{t["hi"]};">{self._docs_inline(cval)}</td>')
                            else:
                                tb.append(f'<td style="color:{t["muted"]};">{self._docs_inline(cval)}</td>')
                        tb.append("</tr>")
                    tb.append("</table><br/>")
                    parts.append("".join(tb))
                    continue
                b = re.match(r"(\s*)([-*]|\d+\.) (.*)", line)
                if b:
                    kind = "ol" if b.group(2)[0].isdigit() else "ul"
                    if in_list != kind:
                        if in_list:
                            parts.append(f"</{in_list}>")
                        parts.append(f"<{kind}>")
                        in_list = kind
                    parts.append(f"<li>{self._docs_inline(b.group(3))}</li>")
                    i += 1; continue
                if in_list:
                    parts.append(f"</{in_list}>"); in_list = None
                if line.startswith(">"):
                    parts.append(f"<blockquote>{self._docs_inline(line.lstrip('> '))}</blockquote>")
                    i += 1; continue
                if line.strip() == "---":
                    parts.append("<hr/>"); i += 1; continue
                if line.strip():
                    parts.append(f"<p>{self._docs_inline(line.strip())}</p>")
                i += 1
            if in_list:
                parts.append(f"</{in_list}>")
            if in_code and code_buf:
                parts.append("<pre>" + self._docs_esc("\n".join(code_buf)) + "</pre>")
            parts.append("<br/><hr/><br/>")
        tx.setHtml("<html><body>" + "".join(parts) + "</body></html>")
        self._docs_anchor_pos = {}
        doc = tx.document()
        blk = doc.begin()
        while blk.isValid():
            it = blk.begin()
            while not it.atEnd():
                frag = it.fragment()
                if frag.isValid():
                    for nm in frag.charFormat().anchorNames():
                        self._docs_anchor_pos.setdefault(nm, frag.position())
                it += 1
            blk = blk.next()
        if not keep_nav or self.docs_nav.count() != len(nav_items):
            self.docs_nav.set_items(nav_items)

    def _docs_jump(self, mark):
        tx = getattr(self, "docs_text", None)
        if tx is None:
            return False
        key, _, anc = str(mark).partition("#")
        name = self._docs_anchor(key, anc)
        if name not in self._docs_anchor_pos:
            return False
        tx.scrollToAnchor(name)
        return True

    def _docs_follow(self, target):
        target = str(target)
        if target.lower().startswith(("http://", "https://")):
            self._market_open_home(target)
            return
        if target.startswith("#"):
            key = "plugins"
            try:
                top = self.docs_text.cursorForPosition(QPoint(0, 0)).position()
                for k, _t, _m in PLUGIN_DOCS:
                    if self._docs_anchor_pos.get(self._docs_anchor(k), 1 << 30) <= top:
                        key = k
            except Exception as _ex:
                _trace(_ex_where(), _ex)
            self._docs_jump(f"{key}{target}")
            return
        page, _, anchor = target.partition("#")
        page = os.path.basename(page)
        if page.endswith(".md"):
            self._docs_jump(f"{page[:-3]}#{anchor}")

    def _docs_nav_pick(self):
        i = self.docs_nav.currentRow()
        if 0 <= i < len(self._docs_nav_marks):
            name = self._docs_nav_marks[i]
            if name in self._docs_anchor_pos:
                self.docs_text.scrollToAnchor(name)

    def _docs_search(self):
        tx = self.docs_text
        q = self.docs_find.get().strip()
        if not q:
            return
        if not tx.find(q):
            cur = tx.textCursor()
            cur.movePosition(QTextCursor.MoveOperation.Start)
            tx.setTextCursor(cur)
            if not tx.find(q):
                self.toast(f"No match for \"{q}\"", "bad")
                return
        tx.ensureCursorVisible()

