    def _render_vms(self, root, found):
        lay = self.vms_list_frame.layout()
        _clear_layout(lay)
        if root:
            self.vms_hint.setText(f"scanned: {root}")
        else:
            _where = "Documents\\Virtual Machines" if platform.system() == "Windows" else ("~/Virtual Machines.localized" if platform.system() == "Darwin" else "~/vmware and ~/Documents")
            self.vms_hint.setText(f"scanned VMware's default location ({_where})")
        if not found:
            lay.addWidget(EmptyState("vms", "No .vmx files found here", "Use the button below to pick your VM folder."))
            return
        for path in found[:40]:
            name = os.path.splitext(os.path.basename(path))[0]
            sel = (os.path.normcase(path) == os.path.normcase(self.vmx_path or ""))
            row = Card(pad=12, tint="accent" if sel else None)
            rl = QHBoxLayout()
            rl.setSpacing(10)
            tx = QVBoxLayout()
            tx.setSpacing(0)
            tx.addWidget(L(name, "hi" if sel else "text", ("mono", 11, "semi" if sel else "normal")))
            dl = L(os.path.dirname(path), "faint", ("ui", 8.5))
            dl.setSizePolicy(QSizePolicy.Policy.Ignored, QSizePolicy.Policy.Preferred)
            tx.addWidget(dl)
            rl.addLayout(tx, 1)
            if sel:
                rl.addWidget(Pill("SELECTED", "accent"))
            rl.addWidget(Button("Select", lambda p=path: self._select_vmx(p), "violet", "sm", icon="check"))
            row.body.addLayout(rl)
            lay.addWidget(row)

    def _select_vmx(self, path):
        self.vmx_path = path
        self.config["vmx_path"] = path
        self.save_settings()
        self.vms_selected_lbl.setText(f"selected: {os.path.basename(path)}")
        self.vmw_status.config(text="status: vm selected - hit 'Enable VNC in .vmx' while it is powered off", fg="accent")
        self._scan_vms(None)

    def _vmw_action(self, action):
        vm = self._vmware()
        if not self.vmx_path:
            self.vmw_status.config(text="status: no .vmx selected", fg="bad"); return
        if not vm.available():
            self.vmw_status.config(text="status: vmrun.exe not found - set the path above", fg="bad"); return

        def _go():
            try:
                if action == "start":
                    ok = vm.start()
                    msg = "vm started" if ok else "start failed (check vmrun path / .vmx)"
                elif action == "stop":
                    vm.stop(); msg = "stop sent"
                elif action == "reset":
                    vm.reset(); msg = "reset sent"
                elif action == "suspend":
                    vm.suspend(); msg = "suspend sent"
                elif action == "kill_vnc":
                    killed = kill_vnc_squatters("manual")
                    msg = (f"stopped: {', '.join(killed)}" if killed
                           else "no host VNC server was running (nothing to stop)")
                elif action == "fix_port":
                    if vm.is_running():
                        msg = "power the VM OFF first, then press this again"
                    else:
                        hit, why = vm.resolve_port_conflict(auto=True)
                        if hit:
                            self.vnc_port = vm.port
                            self.config["vnc_port"] = vm.port
                            self.save_settings()
                            self.ui(lambda p=vm.port: self.vnc_port_entry.setText(str(p)))
                            vm.ensure_vnc_in_vmx()
                            msg = why + " - .vmx updated, start the VM now"
                        else:
                            msg = f"no conflict: port {vm.port} is free for this VM"
                elif action == "forget_pw":
                    try:
                        if os.path.exists(_vpf): os.remove(_vpf)
                        msg = f"cleared {_vpf}"
                    except Exception as e:
                        msg = f"could not clear: {e}"
                elif action == "clear_pw":
                    vm.password = ""
                    self.vnc_password = ""
                    self.config["vnc_password"] = ""
                    self.save_settings()
                    self.ui(self.vnc_pw_entry.clear)
                    if vm.is_running():
                        msg = "power the VM OFF first - the .vmx cannot be edited while it runs"
                    else:
                        vm.ensure_vnc_in_vmx()
                        msg = "vnc password removed from the .vmx - start the VM and test again"
                elif action == "vnc_setup":
                    ok = vm.ensure_vnc_in_vmx()
                    msg = f"vnc enabled in .vmx (port {vm.port}, keymap {vm.keymap})" if ok else "could not edit .vmx"
                elif action == "connect":
                    ok = vm.connect(); msg = vm.status
                elif action == "test":
                    ok, msg = vm.test_connection()
                    info = vm.read_vmx_vnc()
                    self.log("[system]", f"[vmx] enabled={info.get('enabled')} port={info.get('port')} "
                                          f"keymap={info.get('keymap')} password={'SET' if (info.get('password') or info.get('key')) else 'none'}", "sysmsg")
                    self.log("[system]", ("[vnc ok] " if ok else "[vnc fail] ") + msg, "sysmsg" if ok else "err")
                else:
                    msg = "unknown action"
                plog("VMWARE", f"action {action}: {msg}")
                bad = "fail" in msg or "could not" in msg
                self.ui(lambda: self.vmw_status.config(text=f"status: {msg}", fg="bad" if bad else "ok"))
            except Exception as e:
                _emsg = str(e)
                plog("VMWARE", f"action {action} crashed: {type(e).__name__}: {e}")
                self.ui(lambda m=_emsg: self.vmw_status.config(text=f"status: {m}", fg="bad"))
        plog("VMWARE", f"action requested: {action}")
        self.vmw_status.config(text=f"status: {action.replace('_', ' ')}...", fg="muted")
        threading.Thread(target=_go, daemon=True, name=f"vmw-{action}").start()

